(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,46005,e=>{"use strict";var t=e.i(10595),o=e.i(55160);let a={number:7,title:"Review and test",subtitle:"Your error log, a full review and a B2-style test",goal:"See how far you have come this week in a B2-style Use of English test, with your results by topic.",intro:"This is a short test in the style of Cambridge B2 First: in two texts you choose the right word, and in two more you write one word in each gap. It takes about 25 minutes, and at the end you see your results by topic. There is no pass or fail, so take your time and trust your first idea when you are not sure.",part1:[{id:"working-from-home",title:"Working from home: what I've learnt",text:"I have worked from home {{1}} almost two years now. At first I thought it would be easy, but in reality it took me months to find a routine that worked. In the beginning I sat at my desk in my pyjamas and {{2}} off difficult tasks until the afternoon. Then a colleague {{3}} getting dressed every morning as if I were going to the office, and it helped more than I expected.\n\n{{4}} the obvious benefits, working from home has its problems. It is easy to feel lonely, and on some days I hardly speak to anyone. I also used to {{5}} a lot of money on takeaway meals that I did not even enjoy, because cooking seemed like too much trouble.\n\nThe biggest change, {{6}}, was learning to switch off. My manager {{7}} us that nobody wanted replies to emails late at night, and that proper breaks were part of the job. These days I go for a walk at lunchtime, whatever the weather, and I {{8}} a real effort to stop working at six.",gaps:[{options:["since","for","during","ago"],answer:1,category:"perfect",explain:"With the present perfect, for goes with a length of time (almost two years); since needs a starting point, and during and ago do not work with have worked."},{options:["set","took","put","turned"],answer:2,category:"collocations",explain:"Put off means delay something you should do; set off means start a journey, and took off and turned off do not go with tasks."},{options:["told","suggested","persuaded","insisted"],answer:1,category:"verb-patterns",explain:"Suggest is followed directly by -ing (suggested getting dressed); told and persuaded need a person + to, and insist needs on."},{options:["Although","However","Whereas","Despite"],answer:3,category:"linking",explain:"Despite is followed by a noun phrase (the obvious benefits); although and whereas need a full clause, and however cannot join two parts of a sentence."},{options:["waste","spoil","throw","pay"],answer:0,category:"collocations",explain:"We waste money on things that are not worth it; we spoil food or plans, throw money away and pay for something, so none of these fit money on."},{options:["although","unless","however","whereas"],answer:2,category:"linking",explain:"However between commas adds a contrast to the whole sentence; although, unless and whereas must start a new clause."},{options:["said","explained","suggested","told"],answer:3,category:"passive-reported",explain:"Tell is followed directly by a person (told us that…); say, explain and suggest need to before the person (explained to us)."},{options:["do","have","make","take"],answer:2,category:"collocations",explain:"We make an effort to do something; do, have and take do not go with effort."}]},{id:"never-too-late",title:"Never too late",text:"Many people believe that it is too late to learn a language after the age of thirty. However, researchers who {{1}} out a large study in several countries found that this is simply not true. Children usually copy new sounds more easily, {{2}} adults are better at understanding grammar rules and organising what they learn.\n\nWhen I turned forty, I {{3}} to learn Spanish. My teacher gave me a useful {{4}} of advice on the first day: do not be afraid of making mistakes. She also told me to keep a dictionary app on my phone {{5}} I needed a word in a hurry.\n\nOf course, there were weeks when I wanted to stop. Work was busy, I had very {{6}} free time, and I kept forgetting new words. But I soon {{7}} up with a simple system: ten new words on my phone every morning and one short conversation every week. A year later I met some people from Madrid, and they refused to believe that I had learnt Spanish at home. They said I {{8}} have lived in Spain for years.",gaps:[{options:["carried","made","did","took"],answer:0,category:"collocations",explain:"We carry out a study, a survey or research; made out, did out and took out do not mean do a piece of work."},{options:["despite","however","unless","whereas"],answer:3,category:"linking",explain:"Whereas compares two different facts in one sentence; despite needs a noun, unless means if not, and however cannot join two clauses after a comma."},{options:["enjoyed","kept","decided","considered"],answer:2,category:"verb-patterns",explain:"Decide is followed by to + verb; enjoy, keep and consider are followed by -ing."},{options:["number","piece","deal","couple"],answer:1,category:"countable",explain:"Advice is uncountable, so we say a piece of advice; a number of and a couple of need plural nouns, and deal only works as a great deal of."},{options:["in case","unless","so that","otherwise"],answer:0,category:"conditionals",explain:"In case means to be ready if something happens; unless means if not, so that needs a purpose, and otherwise cannot start this clause."},{options:["few","less","small","little"],answer:3,category:"countable",explain:"Time is uncountable, so very little time; few goes with plural nouns, less is a comparative, and small free time would need an article."},{options:["thought","came","made","found"],answer:1,category:"collocations",explain:"Come up with means think of an idea or a plan; thought, made and found do not form a phrase with up with in this meaning."},{options:["must","can't","should","would"],answer:0,category:"modals",explain:"They were sure it was true, so must have + V3 (a confident guess about the past); can't have says the opposite, and should have and would have do not make a guess here."}]}],part2:[{id:"food-festival",title:"A festival that started with five tables",text:"Every September, the old port in our city {{1}} turned into a huge open-air kitchen. The food festival {{2}} first held in 1998, when five local cafés put tables outside for one weekend. Nobody expected it to last, but today it attracts more than 200,000 visitors and is {{3}} largest event of its kind in the country. More and more of them {{4}} now coming from abroad.\n\nWhat makes the festival special is that the food is cooked by ordinary people, not by famous chefs. My neighbour Maria, who has never worked in a restaurant, {{5}} sold her grandmother's fish soup there every year since 2010. {{6}} she made twice as much as usual last year, she still ran out by midday. The festival also goes on late: last year it {{7}} not finish until two in the morning.\n\nIf you are planning to go, come by bus or on foot. Unfortunately, there is very {{8}} information about parking on the official website, and the streets near the port are always full.",gaps:[{answers:["is","gets"],category:"passive-reported",explain:"People turn the port into a kitchen every year, so we need the present simple passive: is turned (or gets turned)."},{answers:["was"],category:"passive-reported",explain:"Past passive: was + V3 (held), because people held the festival for the first time in 1998."},{answers:["the"],category:"articles",explain:"Superlatives take the: the largest event of its kind."},{answers:["are"],category:"tense-choice",explain:"Now and a change that is still going on take the present continuous: are coming."},{answers:["has"],category:"perfect",explain:"Since 2010 joins the past to now, so we need the present perfect: has sold."},{answers:["although","though","while","whilst"],category:"linking",explain:"Although (or though) starts a clause that contrasts with the main one: she made more soup, but she still ran out."},{answers:["did"],category:"be-verb",explain:"Finish is a normal verb, so the past negative is did not finish; was not finish is the classic be mistake."},{answers:["little"],category:"countable",explain:"Information is uncountable, so very little; few is only for plural countable nouns."}]},{id:"first-half-marathon",title:"From the sofa to the finish line",text:"I {{1}} been running for almost two years now, and I still remember how it started. A friend persuaded me to sign up for a half marathon, and I agreed before I had really thought about it. At that point I could not run for more than five minutes.\n\nThe first weeks were hard. One evening a trainer at my gym saw me stop after ten minutes, completely out of breath. “You {{2}} have done much running before,” she said, “or you would not be so tired already.” She also suggested joining a running club, which turned out to be {{3}} excellent idea. I {{4}} not know anyone there at first, but people were friendly and nobody cared about speed. I am not a morning person, but I soon got used {{5}} getting up early on Sundays.\n\nOn the day of the race I finished in two hours and ten minutes. If I {{6}} known how much I would enjoy it, I would have started years ago. My advice is simple: beginners often get injured {{7}} they build up their distance slowly, so be patient. As for me, I {{8}} training for my first full marathon at the moment.",gaps:[{answers:["have"],category:"perfect",explain:"For almost two years now: an action that started in the past and is still going on, so have been running."},{answers:["can't","cannot","couldn't"],category:"modals",explain:"She is sure it is not true (you are this tired already), so can't have + V3; must have would mean she is sure it is true."},{answers:["an"],category:"articles",explain:"Idea is a singular countable noun and excellent starts with a vowel sound, so an."},{answers:["did"],category:"be-verb",explain:"Know is a normal verb, so the past negative is did not know; was not know is wrong."},{answers:["to"],category:"verb-patterns",explain:"Get used to + -ing: to is a preposition here, so it is followed by getting."},{answers:["had"],category:"conditionals",explain:"Third conditional for an imagined past: if + had + V3, would have + V3."},{answers:["unless"],category:"conditionals",explain:"Unless means if not: beginners get injured if they do not build up their distance slowly."},{answers:["am"],category:"tense-choice",explain:"At the moment shows a temporary action in progress, so am + -ing."}]}],speak:[{id:"final-film-had-started",ru:"Я не знал, что фильм уже начался.",en:["I didn't know the film had already started.","I didn't know that the film had already started.","I didn't know the movie had already started.","I didn't know that the movie had already started.","I didn't know the film had started already."],category:"be-verb",focus:"didn't know, had started: no be"},{id:"final-looking-for-job",ru:"Сейчас я ищу новую работу.",en:["I'm looking for a new job at the moment.","I'm looking for a new job now.","At the moment I'm looking for a new job.","I'm looking for a new job right now.","I'm currently looking for a new job."],category:"tense-choice",focus:"temporary → continuous"},{id:"final-lived-since",ru:"Я живу здесь с 2019 года.",en:["I've lived here since 2019.","I've been living here since 2019.","I've lived here since twenty nineteen.","I've been living here since twenty nineteen."],category:"perfect",focus:"have lived + since"},{id:"final-if-i-had-known",ru:"Если бы я тогда знал, я бы тебе сказал.",en:["If I had known, I would have told you.","If I'd known, I'd have told you.","I would have told you if I had known.","If I had known, I'd have told you."],category:"conditionals",focus:"third conditional"},{id:"final-looking-forward",ru:"С нетерпением жду встречи с тобой.",en:["I'm looking forward to seeing you.","I look forward to seeing you.","I'm looking forward to meeting you.","I'm really looking forward to seeing you."],category:"verb-patterns",focus:"look forward to + -ing"},{id:"final-told-to-wait",ru:"Нам сказали подождать.",en:["We were told to wait.","We were asked to wait.","They told us to wait.","We've been told to wait."],category:"passive-reported",focus:"were told + to"},{id:"final-must-have-forgotten",ru:"Он, должно быть, забыл.",en:["He must have forgotten.","He must have forgotten about it.","He must have forgotten it."],category:"modals",focus:"must have + V3"},{id:"final-waste-money",ru:"Не трать деньги впустую.",en:["Don't waste your money.","Don't waste money.","Don't waste your money on it."],category:"collocations",focus:"waste money"},{id:"final-carry-out-survey",ru:"Мы провели опрос клиентов.",en:["We carried out a customer survey.","We carried out a survey of our customers.","We carried out a survey of our clients.","We carried out a survey among our customers.","We conducted a customer survey.","We did a customer survey."],category:"collocations",focus:"carry out a survey"},{id:"final-despite-rain",ru:"Несмотря на дождь, мы пошли гулять.",en:["Despite the rain, we went for a walk.","In spite of the rain, we went for a walk.","Although it was raining, we went for a walk.","Even though it was raining, we went for a walk.","We went for a walk despite the rain.","Despite the rain, we went out for a walk."],category:"linking",focus:"despite + noun"},{id:"final-some-advice",ru:"Можно дать тебе совет?",en:["Can I give you some advice?","Can I give you a piece of advice?","Can I give you a bit of advice?","Could I give you some advice?","May I give you some advice?"],category:"countable",focus:"advice: no a, no -s"},{id:"final-works-as-engineer",ru:"Она работает инженером.",en:["She works as an engineer.","She's an engineer.","She is an engineer."],category:"articles",focus:"a/an with jobs"}]};function n(e,o,a){let n=e.safeParse(o);if(!n.success)throw Error(`Invalid content in ${a}:
${t.z.prettifyError(n.error)}`);return n.data}let i=[{number:1,title:"The tense map",subtitle:"Be + verb, present and past, perfect tenses",goal:"Choose the right tense for everyday situations and stop adding is/am where English does not need it.",topics:[{id:"be-rule",title:"Be + verb: only -ing or V3",summary:"Before another verb, keep be only if that verb is -ing or V3.",category:"be-verb",rules:[{id:"two-partners",title:"Be has only two verb partners",steps:[{kind:"text",text:"When **be** stands right before another verb, that verb must be **-ing** or **V3** (the past participle). No other verb form."},{kind:"formula",parts:["be","+","-ing","=","continuous"]},{kind:"example",en:"I'm working from home today.",ru:"Сегодня я работаю из дома."},{kind:"formula",parts:["be","+","V3","=","passive"]},{kind:"example",en:"The meeting was cancelled.",ru:"Встречу отменили."}]},{id:"no-be",title:"Everything else: no be",steps:[{kind:"text",text:"Present simple and past simple never use be as a helper: the verb itself shows the tense. Watch the verbs Russian speakers most often add be to: **know, agree, depend, live**."},{kind:"table",head:["Wrong","Right"],rows:[["The lesson is start at 9.","The lesson **starts** at 9."],["The film is started at 8.","The film **started** at 8."],["I'm knew it.","I **knew** it."],["I am agree.","I **agree**."],["It is depends on you.","It **depends** on you."],["I'm live in Moscow.","I **live** in Moscow."]]},{kind:"tip",text:"Be on its own is fine with a noun, an adjective or a place: I'm a designer. I'm tired. She's at work. Many feeling words are V3 forms used as adjectives: tired, interested, bored, worried."},{kind:"tip",text:"Be + **to** + verb is a different pattern and is correct: My plan **is to** relax. Our goal **is to** finish by May."}]},{id:"self-check",title:"The self-check",steps:[{kind:"text",text:"Before you say is, am, are, was or were, look at the next word."},{kind:"table",head:["Next word","Keep be?","Example"],rows:[["-ing","Yes","She **is working** late."],["V3","Yes","It **was made** in Italy."],["adjective, noun, place","Yes","I'm **sure**. He's **a doctor**."],["V1, V2 or -s form","No","She **works** here. I **knew** it."]]},{kind:"text",text:"Regular verbs look the same in V2 and V3 (started, moved). Then ask: did someone do it to the subject? Yes → be + V3: The meeting **was moved**. No → no be: The film **started**."},{kind:"example",en:"She works here, but today she's working from home.",ru:"Она работает здесь, но сегодня работает из дома."},{kind:"tip",text:"Next word is a verb, but not **-ing** or **V3**? Delete be."}]}],mistakes:[{wrong:"The film is started at 8.",right:"The film started at 8.",why:"Nobody started the film, so it is not passive: past simple alone shows the past."},{wrong:"I'm knew it.",right:"I knew it.",why:"Knew is V2 (past simple), not -ing or V3, so be has no job here."},{wrong:"I am agree with you.",right:"I agree with you.",why:"Agree is a verb in English, not an adjective like «согласен», so it takes no be."},{wrong:"It is depends on you.",right:"It depends on you.",why:"Depends already shows the tense with -s; be never stands before an -s form."}],ruNote:{text:"В русском в настоящем времени связки нет («я учитель»), и мы привыкаем, что английский требует am/is там, где по-русски пусто. Отсюда лишнее is перед глаголами: I'm live, it is depends. А «я согласен» и «это зависит» звучат как состояние, хотя agree и depend — обычные глаголы: I agree, it depends. Be ставим только перед -ing или V3.",example:{ru:"Я согласен, но это зависит от цены.",en:"I agree, but it depends on the price."}},examples:[{en:"Our flight was delayed by two hours.",ru:"Наш рейс задержали на два часа."},{en:"I'm waiting for a call from the bank.",ru:"Я жду звонка из банка."},{en:"I agree with you about the budget.",ru:"Я согласен с тобой насчёт бюджета."},{en:"It depends on how much time we have.",ru:"Это зависит от того, сколько у нас времени."},{en:"The train left on time.",ru:"Поезд ушёл вовремя."},{en:"She works for a big IT company.",ru:"Она работает в крупной IT-компании."},{en:"We're staying at a small hotel near the station.",ru:"Мы остановились в маленьком отеле у вокзала."},{en:"The meeting was moved to Thursday.",ru:"Встречу перенесли на четверг."},{en:"I knew he was right, but I didn't say anything.",ru:"Я знал, что он прав, но ничего не сказал."},{en:"I'm interested in data analysis, so I'm taking an online course.",ru:"Меня интересует анализ данных, поэтому я прохожу онлайн-курс."}],exercises:[{id:"be-concert-starts",type:"choice",prompt:"The concert ___ at eight, so we have time for dinner first.",options:["is started","is start","starts","starting"],answer:2,rule:"Timetable → present simple; no -ing or V3 → no be",explain:"A timetable uses present simple: starts. Be needs -ing or V3 after it, and 'is started' would be passive.",ruHint:"Расписание — present simple: starts, без is."},{id:"be-bike-stolen",type:"choice",prompt:"My bike ___ last night, so I took a taxi to work.",options:["stole","is stolen","was stealing","was stolen"],answer:3,rule:"be + V3 = passive: someone did it to the bike",explain:"The bike didn't steal anything: someone stole it. That is passive, past: was + V3 (stolen).",ruHint:"«Велосипед украли» — пассив: was stolen."},{id:"be-depends-on",type:"collocation",prompt:"Whether we fly or take the train depends ___ the price.",options:["from","on","of","at"],answer:1,rule:"depend on (not from); it depends, no be",explain:"In English you depend on something. 'Depends from' is a word-for-word copy of «зависит от».",ruHint:"«Зависит от» = depends on."},{id:"be-film-started",type:"fill",before:"Hurry up! The film ",after:" ten minutes ago.",answers:["started"],base:"start",rule:"Past simple: V2 alone, no is/was",explain:"'Ten minutes ago' is finished time, so use past simple: started. 'Is started' or 'was started' would be passive.",ruHint:"«Фильм начался» — просто started, без is и was."},{id:"be-i-agree",type:"fill",before:"You're right — I ",after:" with you about the price.",answers:["agree","totally agree","completely agree","fully agree","absolutely agree"],base:"agree",rule:"agree is a verb: I agree (not I am agree)",explain:"In English agree is a normal verb, just like want or need. It needs no am: I agree.",ruHint:"«Я согласен» = I agree, без am."},{id:"be-belongs-to",type:"errorTap",sentence:"This laptop is belongs to my manager, not to me.",wrong:2,correct:"This laptop belongs to my manager, not to me.",rule:"No be before an -s form: delete be",explain:"Belongs is present simple with -s. It is not -ing or V3, so 'is' must go.",ruHint:"Перед формой на -s is не ставится — убери его."},{id:"be-photo-taken",type:"reorder",words:["where","was","this","photo","taken"],end:"?",rule:"be + V3 = passive question: was … taken",explain:"The photo didn't take anything: someone took it. Passive question: where + was + subject + V3.",ruHint:"«Где сделали это фото?» — пассив: was taken."}]},{id:"present-simple-continuous",title:"Present simple or continuous?",summary:"Habits, facts and timetables vs what is happening now or for a while.",category:"tense-choice",rules:[{id:"habit-vs-now",title:"Always true or true around now?",steps:[{kind:"table",head:["Present simple","Present continuous"],rows:[["habits: I **go** to the gym twice a week.","now: I'**m talking** to a client."],["facts: Water **boils** at 100°C.","temporary: I'**m staying** with friends this month."],["timetables: The train **leaves** at 7.15.","changing: Prices **are going** up."],["permanent: She **lives** in Kazan.","in progress: We'**re renovating** the kitchen."]]},{kind:"signals",items:[{word:"usually, often, every day",use:"habit → present simple"},{word:"always, never, sometimes",use:"how often → simple (always + -ing = annoyed)"},{word:"now, right now, at the moment",use:"happening as we speak → continuous"},{word:"these days, currently, this month",use:"temporary period → continuous"}]},{kind:"example",en:"I usually work from the office, but this week I'm working from home.",ru:"Обычно я работаю в офисе, но на этой неделе работаю из дома."}]},{id:"state-verbs",title:"State verbs: no -ing",steps:[{kind:"text",text:"Some verbs describe **states**, not actions. They normally stay in present simple, even when you mean right now. A few also have an action meaning: see the next card."},{kind:"table",head:["Group","Verbs"],rows:[["mind","know, believe, understand, mean, think (= opinion)"],["likes and wants","like, love, hate, want, need, prefer"],["other states","agree, belong, seem, depend, own"]]},{kind:"example",en:"I know what you mean.",ru:"Я понимаю, что ты имеешь в виду."},{kind:"tip",text:"Not I'm knowing, I'm wanting. Even with now: I understand now (not I'm understanding now)."}]},{id:"two-meanings",title:"Think, have, see: two meanings",steps:[{kind:"table",head:["State (simple)","Action (continuous)"],rows:[["I **think** it's a good idea. (opinion)","I'**m thinking** about changing jobs. (considering)"],["I **have** two kids. (own)","I'**m having** lunch. (eating)"],["I **see** what you mean. (understand)","I'**m seeing** a client at 3. (meeting)"]]},{kind:"tip",text:"Ask: is it a state (an opinion, owning, understanding) or an action going on? State → simple. Action → continuous."}]}],mistakes:[{wrong:"I'm knowing the answer.",right:"I know the answer.",why:"Know is a state verb, so it stays in present simple."},{wrong:"Every morning I'm drinking coffee.",right:"Every morning I drink coffee.",why:"Every morning is a habit, so use present simple."},{wrong:"Look! It rains.",right:"Look! It's raining.",why:"It is happening right now, so use present continuous."},{wrong:"I'm thinking it's a good idea.",right:"I think it's a good idea.",why:"For an opinion, think is a state verb. I'm thinking means I'm considering."}],ruNote:{text:"В русском одно настоящее время: «я работаю» — и обычно, и прямо сейчас. В английском это два разных времени: I work (вообще, привычка) и I'm working (сейчас или временно). Спросите себя: это всегда так или только в этот период? Глаголы состояния (know, want, like, need) в -ing обычно не ставим, даже если речь о «сейчас».",example:{ru:"Я живу в Казани, но сейчас живу у друзей в Москве.",en:"I live in Kazan, but I'm staying with friends in Moscow at the moment."}},examples:[{en:"I usually cycle to work, but today I'm taking the bus.",ru:"Обычно я езжу на работу на велосипеде, но сегодня еду на автобусе."},{en:"What do you do for a living?",ru:"Кем ты работаешь?"},{en:"We're renovating our kitchen, so we're eating out a lot.",ru:"У нас ремонт на кухне, поэтому мы часто едим в кафе."},{en:"The shop opens at ten on Sundays.",ru:"По воскресеньям магазин открывается в десять."},{en:"More and more people are working remotely these days.",ru:"Сейчас всё больше людей работают удалённо."},{en:"I don't understand why the tickets are so expensive.",ru:"Не понимаю, почему билеты такие дорогие."},{en:"She's looking for a flat closer to the city centre.",ru:"Она ищет квартиру поближе к центру."},{en:"I'm thinking of taking a week off in May.",ru:"Подумываю взять неделю отпуска в мае."},{en:"We need more time to finish the project.",ru:"Нам нужно больше времени, чтобы закончить проект."},{en:"My English is slowly getting better.",ru:"Мой английский потихоньку становится лучше."}],exercises:[{id:"psc-having-dinner",type:"choice",prompt:"Can I call you back? We ___ dinner right now.",options:["have","are having","having","have had"],answer:1,rule:"right now → am/is/are + -ing",explain:"'Right now' means the action is in progress, so use are having. Here have means eat, an action, so -ing is fine.",ruHint:"«Прямо сейчас ужинаем» — are having."},{id:"psc-dont-understand",type:"choice",prompt:"Sorry, I ___ what you mean. Could you explain it again?",options:["am not understanding","not understand","don't understand","am not understand"],answer:2,rule:"State verbs (know, understand) → present simple",explain:"Understand is a state verb, so it stays in present simple even when you mean now: I don't understand.",ruHint:"understand — глагол состояния: I don't understand."},{id:"psc-at-the-moment",type:"collocation",prompt:"Anna can't come to the phone at the ___ — she's in a meeting.",options:["moment","now","present","currently"],answer:0,rule:"at the moment = now → present continuous",explain:"The fixed phrase is 'at the moment'. You can also say 'right now' or 'currently', but without 'at the'.",ruHint:"«В данный момент» = at the moment."},{id:"psc-staying",type:"fill",before:"I live in Kazan, but this month I ",after:" with my parents in Samara.",answers:["'m staying","am staying"],base:"stay",rule:"Temporary situation → present continuous",explain:"'This month' shows a temporary situation, so use present continuous: I'm staying. 'I live in Kazan' is permanent.",ruHint:"Временно — present continuous: I'm staying."},{id:"psc-usually-goes",type:"fill",before:"She usually ",after:" to work by metro, but today she's driving.",answers:["goes"],base:"go",rule:"usually → present simple; he/she/it + -s",explain:"'Usually' shows a habit, so use present simple. With she, add -s: goes.",ruHint:"Привычка — present simple: she goes."},{id:"psc-baby-sleeping",type:"errorTap",sentence:"The baby sleeps right now, so please be quiet.",wrong:2,correct:"The baby is sleeping right now, so please be quiet.",rule:"right now → be + -ing, not present simple",explain:"The action is in progress at this moment, so use present continuous: is sleeping.",ruHint:"«Прямо сейчас» — is sleeping, а не sleeps."},{id:"psc-working-on",type:"reorder",words:["what","are","you","working","on","at","the","moment"],end:"?",alt:[["at","the","moment","what","are","you","working","on"]],rule:"Now or temporary → present continuous question",explain:"Present continuous question: what + are + you + -ing. The preposition on stays after the verb.",ruHint:"«Над чем ты сейчас работаешь?» — on стоит после глагола."}]},{id:"past-simple-present-perfect",title:"Past simple or present perfect?",summary:"Finished time → past simple. A link to now → present perfect.",category:"perfect",rules:[{id:"finished-time",title:"Finished time → past simple",steps:[{kind:"text",text:"If you say or think **when** it happened, and that time is over, use past simple."},{kind:"signals",items:[{word:"yesterday, last week, in 2019",use:"finished time → past simple"},{word:"two days ago",use:"ago → past simple"},{word:"When…? / when I was a child",use:"a point in the past → past simple"}]},{kind:"example",en:"We moved to Moscow in 2019.",ru:"Мы переехали в Москву в 2019 году."},{kind:"tip",text:"When did you…? always takes past simple: When did you arrive? (not When have you arrived?)"}]},{id:"link-to-now",title:"A link to now → present perfect",steps:[{kind:"formula",parts:["have / has","+","V3"]},{kind:"table",head:["Use","Example"],rows:[["life experience, no time said","I've **been** to Japan twice."],["result now","I've **lost** my keys. (I can't get in.)"],["unfinished period","I've **had** three coffees today."],["from the past until now","We've **known** each other for years."]]},{kind:"signals",items:[{word:"just",use:"a moment ago: I've just arrived"},{word:"already",use:"sooner than expected: I've already paid"},{word:"yet",use:"questions and negatives, at the end: Not yet."},{word:"ever, never",use:"life experience"},{word:"so far, today, this week",use:"the period is not over"}]},{kind:"tip",text:"Present perfect never goes with a finished time: not I've seen him yesterday. In American English past simple is also common with just, already, yet: I just saw it."}]},{id:"since-for",title:"Since or for?",steps:[{kind:"table",head:["for + a period","since + a start point"],rows:[["for ten years","since 2015"],["for two weeks","since Monday"],["for a long time","since I was a child"],["for ages","since we met"]]},{kind:"example",en:"I've worked here since March.",ru:"Я работаю здесь с марта."},{kind:"tip",text:"Russian says «живу здесь с 2020» in the present, but English needs present perfect: I've lived here since 2020 (not I live here since 2020)."}]}],mistakes:[{wrong:"I have seen him yesterday.",right:"I saw him yesterday.",why:"Yesterday is finished time, so use past simple."},{wrong:"I live here since 2020.",right:"I've lived here since 2020.",why:"From a past point until now needs present perfect with since."},{wrong:"How long do you know him?",right:"How long have you known him?",why:"How long … up to now needs present perfect: have you known, not do you know."},{wrong:"When have you arrived?",right:"When did you arrive?",why:"A question with when asks about a finished time, so use past simple."}],ruNote:{text:"В русском одно прошедшее время: «я потерял ключи» — и вчера, и только что. В английском выбор зависит от того, назван ли законченный момент: вчера, в 2019, неделю назад — past simple; важен результат сейчас или опыт — present perfect. А «живу здесь с 2020» по-русски звучит в настоящем, но по-английски это present perfect: I've lived here since 2020.",example:{ru:"Я уже прочитал отчёт — прочитал вчера вечером.",en:"I've already read the report — I read it last night."}},examples:[{en:"Have you ever been to Istanbul?",ru:"Ты когда-нибудь был в Стамбуле?"},{en:"We went to Istanbul last spring.",ru:"Мы ездили в Стамбул прошлой весной."},{en:"I've just sent you the file.",ru:"Я только что отправил тебе файл."},{en:"Has the parcel arrived yet?",ru:"Посылка уже пришла?"},{en:"I haven't decided yet.",ru:"Я ещё не решил."},{en:"She's worked here since 2021.",ru:"Она работает здесь с 2021 года."},{en:"We've known each other for over ten years.",ru:"Мы знакомы больше десяти лет."},{en:"I lost my phone last week, but luckily someone found it and called me.",ru:"На прошлой неделе я потерял телефон, но, к счастью, кто-то его нашёл и позвонил мне."},{en:"I've had three meetings today, and it's only noon.",ru:"Сегодня у меня уже было три встречи, а ещё только полдень."},{en:"When did you start learning English?",ru:"Когда ты начал учить английский?"}],exercises:[{id:"pp-met-yesterday",type:"choice",prompt:"I ___ Mark at the conference yesterday.",options:["have met","met","have meet","am meeting"],answer:1,rule:"Finished time (yesterday) → past simple",explain:"Yesterday is finished time, so use past simple: met. Present perfect never goes with yesterday.",ruHint:"С yesterday — только past simple."},{id:"pp-how-long-known",type:"choice",prompt:"How long ___ you known Anna?",options:["do","did","have","are"],answer:2,rule:"How long + up to now → have + V3",explain:"Known is V3, and the question is about a period up to now, so use have: How long have you known Anna?",ruHint:"«Сколько вы знакомы?» — How long have you known…?"},{id:"pp-just-finished",type:"collocation",prompt:"I've ___ finished the report — I'll send it to you in a minute.",options:["just","yet","ago","since"],answer:0,rule:"just = a moment ago; goes between have and V3",explain:"Just means a very short time ago and sits between have and V3. Yet goes at the end, and ago needs past simple.",ruHint:"«Только что» = just: I've just finished."},{id:"pp-lived-since",type:"fill",before:"I ",after:" in this flat since 2020, and I still love it.",answers:["'ve lived","have lived","'ve been living","have been living"],base:"live",rule:"since + start point → have + V3",explain:"It started in 2020 and is still true, so use present perfect: I've lived. Russian uses the present here, English does not.",ruHint:"«Живу здесь с 2020» — I've lived here since 2020."},{id:"pp-went-ago",type:"fill",before:"We ",after:" to Spain two years ago, and we loved it.",answers:["went"],base:"go",rule:"ago → past simple",explain:"'Two years ago' is a finished time, so use past simple: went.",ruHint:"С ago — всегда past simple."},{id:"pp-for-ten-years",type:"errorTap",sentence:"We have known each other since ten years, but we rarely meet.",wrong:5,correct:"We have known each other for ten years, but we rarely meet.",rule:"for + a period, since + a start point",explain:"Ten years is a period, so use for. Since needs a start point: since 2015, since school.",ruHint:"for — сколько времени, since — с какого момента."},{id:"pp-ever-been",type:"reorder",words:["have","you","ever","been","to","London"],end:"?",rule:"Life experience → Have you ever been to…?",explain:"For life experience with no time, use present perfect. With been, use to before a place.",ruHint:"«Ты когда-нибудь был в…?» — Have you ever been to…?"}]},{id:"past-perfect",title:"Past perfect: the earlier past",summary:"had + V3 shows which of two past actions happened first.",category:"perfect",rules:[{id:"two-past-actions",title:"Two past actions",steps:[{kind:"formula",parts:["had","+","V3"]},{kind:"text",text:"Use past perfect for the action that happened **before** another past moment. The later action is in past simple."},{kind:"example",en:"When I arrived, the lesson had already started.",ru:"Когда я пришёл, урок уже начался."},{kind:"tip",text:"Had + V3, not was + V3: the lesson **had started** (it started earlier). 'Was started' is passive, as if someone started the lesson."}]},{id:"when-order",title:"When: which came first?",steps:[{kind:"table",head:["Sentence","What happened"],rows:[["When I arrived, the lesson **started**.","I arrived → then it started."],["When I arrived, the lesson **had started**.","It started → then I arrived (late)."],["When we got to the station, the train **left**.","We got there → then it left."],["When we got to the station, the train **had left**.","It left → then we got there (missed it)."]]},{kind:"tip",text:"If the order is clear from before or after, past simple is also fine: I left after I had finished = I left after I finished."}]},{id:"signal-words",title:"Signal words",steps:[{kind:"signals",items:[{word:"by the time",use:"By the time I arrived, everyone had left."},{word:"already",use:"between had and V3: had already gone"},{word:"just",use:"a moment before: had just left"},{word:"never … before",use:"no experience until then: had never flown before"},{word:"before, after",use:"order is already clear; past simple is fine too"},{word:"when",use:"check the order: started or had started?"}]},{kind:"example",en:"By the time we found a taxi, the concert had finished.",ru:"К тому времени, как мы нашли такси, концерт уже закончился."},{kind:"example",en:"I had never tried sushi before I went to Japan.",ru:"До поездки в Японию я ни разу не пробовал суши."}]}],mistakes:[{wrong:"When I arrived, the lesson was already started.",right:"When I arrived, the lesson had already started.",why:"The lesson started by itself, before I came: had + V3, not was + V3."},{wrong:"By the time we got there, everyone left.",right:"By the time we got there, everyone had left.",why:"Everyone left before we arrived: with by the time, the earlier action takes had + V3."},{wrong:"I didn't know her because I never met her before.",right:"I didn't know her because I had never met her before.",why:"Never … before a past moment → had never + V3."},{wrong:"Yesterday I had gone to the cinema.",right:"Yesterday I went to the cinema.",why:"Past perfect is not a «more past» tense: it needs a later past moment. One past action → past simple."}],ruNote:{text:"В русском нет отдельного «предпрошедшего» времени: «когда я пришёл, урок уже начался» — оба глагола в прошедшем, а порядок понятен из «уже». В английском порядок показывает грамматика: had started — началось раньше другого события. Не путайте с «был начат»: was started — это пассив, как будто кто-то начал урок.",example:{ru:"Когда мы приехали на вокзал, поезд уже ушёл.",en:"When we got to the station, the train had already left."}},examples:[{en:"When I got home, the kids had already gone to bed.",ru:"Когда я вернулся домой, дети уже легли спать."},{en:"By the time the meeting started, I had read all the documents.",ru:"К началу встречи я уже прочитал все документы."},{en:"We had just left the house when it started to rain.",ru:"Не успели мы выйти из дома, как пошёл дождь."},{en:"She had never flown before, so she was a bit nervous.",ru:"Она раньше никогда не летала, поэтому немного нервничала."},{en:"I realised I had left my laptop on the train.",ru:"Я понял, что оставил ноутбук в поезде."},{en:"They had been married for ten years when they moved abroad.",ru:"Они были женаты десять лет, когда переехали за границу."},{en:"After we had checked out of the hotel, we went to the beach.",ru:"Выехав из отеля, мы пошли на пляж."},{en:"When I called him, he had already made a decision.",ru:"Когда я ему позвонил, он уже принял решение."},{en:"The film had already started when we found our seats.",ru:"Когда мы нашли свои места, фильм уже начался."},{en:"I didn't recognise him because he had grown a beard.",ru:"Я его не узнал, потому что он отрастил бороду."}],exercises:[{id:"pf-train-had-left",type:"choice",prompt:"We got to the station at 9:05, but the train ___ five minutes earlier.",options:["has left","had left","was left","is left"],answer:1,rule:"Earlier of two past actions → had + V3",explain:"The train left before we arrived, so use past perfect: had left. 'Was left' is passive and means someone left the train.",ruHint:"Поезд ушёл раньше, чем мы пришли — had left."},{id:"pf-stopped-talking",type:"choice",prompt:"The students were noisy, but when the teacher walked in, they ___ talking immediately.",options:["stopped","had stopped","were stopped","have stopped"],answer:0,rule:"One action right after another → past simple",explain:"First the teacher walked in, then they stopped talking. When things happen in that order, use past simple for both.",ruHint:"Сначала вошёл учитель, потом все замолчали — оба глагола в past simple."},{id:"pf-by-the-time",type:"collocation",prompt:"By the ___ we found a parking space, the show had started.",options:["when","moment","hour","time"],answer:3,rule:"by the time (not by the moment) + past perfect",explain:"The fixed phrase is 'by the time'. 'By the moment' is a word-for-word copy of «к тому моменту».",ruHint:"«К тому времени, как» = by the time."},{id:"pf-had-gone-home",type:"fill",before:"When I got to the office, everyone ",after:" home. The building was empty.",answers:["had gone","'d gone","had already gone","'d already gone"],base:"go",rule:"Earlier past action → had + V3",explain:"They went home before I arrived, so use past perfect: had gone.",ruHint:"Ушли раньше, чем я пришёл — had gone."},{id:"pf-never-given",type:"fill",before:"I was nervous because I ",after:" a presentation in English before.",answers:["had never given","'d never given"],base:"never / give",rule:"never … before a past moment → had never + V3",explain:"The experience is counted up to a moment in the past, so use past perfect: had never given.",ruHint:"Ни разу до того момента — had never given."},{id:"pf-concert-had-started",type:"errorTap",sentence:"When we arrived, the concert was already started, so we missed the first song.",wrong:5,correct:"When we arrived, the concert had already started, so we missed the first song.",rule:"had + V3 for the earlier action, not was + V3",explain:"The concert started before we arrived: had started. 'Was started' is passive, as if someone started the concert.",ruHint:"«Уже начался» — had already started, а не was."},{id:"pf-everyone-had-left",type:"reorder",words:["by","the","time","I","arrived","everyone","had","left"],alt:[["everyone","had","left","by","the","time","I","arrived"]],rule:"by the time + past simple; earlier action: had + V3",explain:"By the time + past simple gives the later moment; the earlier action takes past perfect: had left.",ruHint:"Когда я пришёл, все уже ушли — had left."}]}],speak:[{id:"speak-film-started",ru:"Фильм начался в восемь.",en:["The film started at eight.","The movie started at eight.","The film began at eight.","The movie began at eight.","The film started at 8."],category:"be-verb",focus:"past simple, no be"},{id:"speak-i-agree",ru:"Я согласен с тобой.",en:["I agree with you."],category:"be-verb",focus:"agree is a verb"},{id:"speak-it-depends",ru:"Это зависит от цены.",en:["It depends on the price.","That depends on the price."],category:"be-verb",focus:"depends on, no be"},{id:"speak-i-knew-it",ru:"Я так и знал!",en:["I knew it!","I knew it."],category:"be-verb",focus:"knew, no be"},{id:"speak-flight-cancelled",ru:"Наш рейс отменили.",en:["Our flight was cancelled.","Our flight has been cancelled.","Our flight's been cancelled.","Our flight was canceled.","Our flight got cancelled."],category:"be-verb",focus:"be + V3 = passive"},{id:"speak-working-from-home",ru:"Сегодня я работаю из дома.",en:["I'm working from home today.","I am working from home today.","Today I'm working from home.","Today I am working from home."],category:"tense-choice",focus:"temporary → continuous"},{id:"speak-usually-get-up",ru:"Обычно я встаю в семь.",en:["I usually get up at seven.","I usually get up at 7.","Usually I get up at seven.","I usually wake up at seven."],category:"tense-choice",focus:"habit → present simple"},{id:"speak-what-are-you-reading",ru:"Что ты сейчас читаешь?",en:["What are you reading now?","What are you reading at the moment?","What are you reading right now?","What are you reading?"],category:"tense-choice",focus:"now → continuous"},{id:"speak-lived-five-years",ru:"Я живу в Москве уже пять лет.",en:["I've lived in Moscow for five years.","I have lived in Moscow for five years.","I've been living in Moscow for five years.","I have been living in Moscow for five years."],category:"perfect",focus:"for + present perfect"},{id:"speak-not-decided-yet",ru:"Я ещё не решил.",en:["I haven't decided yet.","I have not decided yet.","I've not decided yet."],category:"perfect",focus:"yet + present perfect"},{id:"speak-ever-been-london",ru:"Ты когда-нибудь был в Лондоне?",en:["Have you ever been to London?"],category:"perfect",focus:"ever + present perfect"},{id:"speak-lesson-had-started",ru:"Когда я пришёл, урок уже начался.",en:["When I arrived, the lesson had already started.","When I came, the lesson had already started.","When I got there, the lesson had already started.","The lesson had already started when I arrived."],category:"perfect",focus:"had + V3, not was + V3"}],phrases:[{en:"I agree with you.",ru:"Я с тобой согласен.",category:"be-verb"},{en:"It depends on the price.",ru:"Это зависит от цены.",category:"be-verb"},{en:"The meeting was cancelled.",ru:"Встречу отменили.",category:"be-verb"},{en:"I'm interested in design.",ru:"Меня интересует дизайн.",category:"be-verb"},{en:"at the moment",ru:"в данный момент, сейчас",category:"tense-choice"},{en:"I'm thinking of changing jobs.",ru:"Подумываю сменить работу.",category:"tense-choice"},{en:"I haven't decided yet.",ru:"Я ещё не решил.",category:"perfect"},{en:"I've just sent it.",ru:"Я только что это отправил.",category:"perfect"},{en:"We've known each other for years.",ru:"Мы знакомы много лет.",category:"perfect"},{en:"Have you ever been to…?",ru:"Ты когда-нибудь был в…?",category:"perfect"},{en:"So far, so good.",ru:"Пока всё идёт хорошо.",category:"perfect"},{en:"by the time I got there",ru:"к тому времени, как я туда добрался",category:"perfect"}]},{number:2,title:"Conditionals",subtitle:"Zero to third, mixed conditionals and wish",goal:"Talk about real, imagined and past situations with if, and say what you wish were different, without putting will or would after if.",topics:[{id:"zero-first",title:"Zero and first conditional",summary:"Facts and a real future: present simple after if, will only in the result.",category:"conditionals",rules:[{id:"zero",title:"Zero conditional: always true",steps:[{kind:"text",text:"For facts and things that happen **every time**, use present simple in both parts. Here if means 'every time', so you can often say **when** instead."},{kind:"formula",parts:["If","+","present simple","→","present simple"]},{kind:"example",en:"If you heat ice, it melts.",ru:"Если нагреть лёд, он тает."},{kind:"example",en:"If I work late, I take a taxi home.",ru:"Если я задерживаюсь на работе, я еду домой на такси."}]},{id:"first",title:"First conditional: a real future",steps:[{kind:"text",text:"Use it for something that **may really happen** in the future, and its likely result."},{kind:"formula",parts:["If","+","present simple","→","will","+","V1"]},{kind:"example",en:"If it rains tomorrow, I'll stay at home.",ru:"Если завтра будет дождь, я останусь дома."},{kind:"tip",text:"The result can also be an instruction or another modal: If you see Anna, **tell** her to call me. If the train is late, we **might** miss the start."},{kind:"tip",text:"Either half can come first. Use a comma only when the if-part comes first: If it rains, I'll stay in. I'll stay in if it rains."}]},{id:"no-will",title:"No will after if, when, unless",steps:[{kind:"text",text:"After **if, when, unless, as soon as, before, after, until** and **in case**, talk about the future with **present simple**, even where Russian says «будет». Will goes only in the result."},{kind:"table",head:["Wrong","Right"],rows:[["If it will rain, we'll stay in.","If it **rains**, we'll stay in."],["I'll call you when I will arrive.","I'll call you when I **arrive**."],["Wait here until I will come back.","Wait here until I **come** back."],["We won't go unless it will stop raining.","We won't go unless it **stops** raining."]]},{kind:"signals",items:[{word:"if",use:"it may happen: If I get the job, we'll celebrate."},{word:"when",use:"it will happen: When I get home, I'll call you."},{word:"unless",use:"= if not: Unless you hurry, you'll miss the bus."},{word:"as soon as",use:"right after: I'll text you as soon as I land."},{word:"until",use:"= «пока не», no not: Wait here until I come back."},{word:"in case",use:"just to be safe: Take a coat in case it gets cold."}]},{kind:"tip",text:"Present perfect also works when the first action must be finished: I'll call you when I**'ve finished**."}]}],mistakes:[{wrong:"If it will rain tomorrow, we'll stay at home.",right:"If it rains tomorrow, we'll stay at home.",why:"After if, use present simple for the future; will goes only in the result."},{wrong:"I'll call you when I will get home.",right:"I'll call you when I get home.",why:"When, as soon as, before and until work like if: present simple for the future."},{wrong:"Unless you don't hurry, you'll miss the train.",right:"Unless you hurry, you'll miss the train.",why:"Unless already means 'if not', so a second not makes a double negative."},{wrong:"In case if you need anything, just call me.",right:"If you need anything, just call me.",why:"«В случае, если» is simply if; 'in case if' is not English, and in case alone means 'just to be safe'."}],ruNote:{text:"По-русски мы говорим «если будет дождь», «когда приеду» — в будущем времени, и рука сама тянется к will. В английском после if, when, unless, as soon as и until будущее передаётся настоящим временем: if it rains, when I arrive. Will ставим только в ту часть, где результат. И помните: unless и until уже содержат «не», второе отрицание не нужно.",example:{ru:"Позвоню тебе, как только доберусь.",en:"I'll call you as soon as I get there."}},examples:[{en:"If you mix red and yellow, you get orange.",ru:"Если смешать красный и жёлтый, получится оранжевый."},{en:"If I don't get enough sleep, I get a headache.",ru:"Если я не высыпаюсь, у меня болит голова."},{en:"If the weather's nice tomorrow, we'll have lunch outside.",ru:"Если завтра будет хорошая погода, пообедаем на улице."},{en:"If I'm late, start without me.",ru:"Если я опоздаю, начинайте без меня."},{en:"I'll send you the details as soon as I get them.",ru:"Пришлю тебе подробности, как только получу."},{en:"We won't get there on time unless we leave now.",ru:"Мы не успеем, если не выйдем прямо сейчас."},{en:"When you get to the hotel, ask for a room with a view.",ru:"Когда доберёшься до отеля, попроси номер с видом."},{en:"If the bank approves the loan, we'll buy the flat in spring.",ru:"Если банк одобрит кредит, весной купим квартиру."},{en:"Don't sign anything until you've read the contract.",ru:"Ничего не подписывай, пока не прочитаешь договор."},{en:"If you're not happy with it, you can return it within 14 days.",ru:"Если вам не понравится, его можно вернуть в течение 14 дней."}],exercises:[{id:"zf-if-it-rains",type:"choice",prompt:"If it ___ tomorrow, we'll move the party indoors.",options:["will rain","would rain","rains","rained"],answer:2,rule:"if + present simple; will only in the result",explain:"In the if-part, use present simple for the future: if it rains. Will goes only in the result: we'll move.",ruHint:"«Если будет дождь» — if it rains, без will."},{id:"zf-unless-book",type:"choice",prompt:"You won't get a table at that restaurant ___ you book in advance.",options:["if","unless","when","as soon as"],answer:1,rule:"unless = if not",explain:"The meaning is 'if you don't book'. Unless already contains the not: unless you book.",ruHint:"«Если не забронируешь» = unless you book."},{id:"zf-as-soon-as",type:"collocation",prompt:"I'll text you as ___ as I land, probably around ten.",options:["fast","early","soon","quick"],answer:2,rule:"as soon as + present simple = right after",explain:"The fixed phrase is 'as soon as'. After it, use present simple for the future: as soon as I land.",ruHint:"«Как только» = as soon as."},{id:"zf-when-arrive",type:"fill",before:"I'll call you when I ",after:" at the airport.",answers:["arrive","'ve arrived","have arrived"],base:"arrive",rule:"when + present simple for the future",explain:"After when, use present simple for the future, just like after if: when I arrive. Not when I will arrive.",ruHint:"«Когда приеду» — when I arrive, без will."},{id:"zf-anna-drinks",type:"fill",before:"If Anna ",after:" coffee after 6 pm, she can't sleep.",answers:["drinks"],base:"drink",rule:"Zero conditional: present simple in both parts",explain:"It happens every time, so both parts are in present simple. With she, add -s: drinks.",ruHint:"«Каждый раз, когда» — present simple: she drinks."},{id:"zf-as-soon-as-hear",type:"errorTap",sentence:"Please call me as soon as you will hear any news.",wrong:7,correct:"Please call me as soon as you hear any news.",rule:"No will after as soon as, when, if",explain:"As soon as works like if and when: present simple for the future. Delete will: as soon as you hear.",ruHint:"«Как только узнаешь» — as soon as you hear, без will."},{id:"zf-unless-come",type:"reorder",words:["I","won't","go","unless","you","come","with","me"],alt:[["unless","you","come","with","me","I","won't","go"]],rule:"unless + present simple = if not",explain:"Unless means 'if not' and takes present simple: unless you come. The result has will: I won't go.",ruHint:"«Если ты не пойдёшь со мной» = unless you come with me, без второго not."}]},{id:"second",title:"Second conditional: imagine",summary:"An unreal now or an unlikely future: if + past simple, would + verb.",category:"conditionals",rules:[{id:"unreal-now",title:"Imagine a different now",steps:[{kind:"formula",parts:["If","+","past simple","→","would","+","V1"]},{kind:"text",text:"The past form here does not mean past time. It means **not real**: an imagined situation now, or a future you don't really expect."},{kind:"example",en:"If I had more time, I'd travel more.",ru:"Если бы у меня было больше времени, я бы больше путешествовал."},{kind:"tip",text:"Would is usually shortened to **'d**. Could and might also work in the result: If I had a car, I **could** pick you up."}]},{id:"would-were",title:"Would stays out of the if-part",steps:[{kind:"text",text:"Russian puts «бы» in both halves. English puts **would** only in the result; the if-part takes past simple. With be, use **were** for every person."},{kind:"table",head:["Wrong","Right"],rows:[["If I would have money, I'd buy it.","If I **had** money, I'd buy it."],["If he would know, he'd tell us.","If he **knew**, he'd tell us."],["If I would be you, I'd wait.","If I **were** you, I'd wait."]]},{kind:"example",en:"If I were you, I'd take the job.",ru:"На твоём месте я бы согласился на эту работу."},{kind:"tip",text:"In everyday speech you will also hear if I was or if it was. **Were** is always correct, and the fixed phrase for advice is **If I were you**."},{kind:"tip",text:"One exception: in polite requests would can follow if, because it means 'be willing to': I'd be grateful if you **would** reply by Friday."}]},{id:"first-or-second",title:"First or second: how real is it?",steps:[{kind:"table",head:["First: may really happen","Second: imagined or unlikely"],rows:[["If I **see** Tom, I'**ll tell** him. (I'll see him at work.)","If I **saw** Tom, I'**d tell** him. (I never see him.)"],["If you **come** to Kazan, you'**ll love** it. (You're planning to.)","If you **came** to Kazan, you'**d love** it. (You have no plans.)"],["If I **win** the match, I'**ll buy** dinner.","If I **won** the lottery, I'**d stop** working."]]},{kind:"tip",text:"Ask yourself: is this a real plan or chance, or am I just imagining it? Real → first conditional. Imagined → second."}]}],mistakes:[{wrong:"If I would have more money, I would buy a flat.",right:"If I had more money, I would buy a flat.",why:"Would never goes in the if-part: after if, use past simple."},{wrong:"If I were you, I will talk to him.",right:"If I were you, I'd talk to him.",why:"An imagined situation takes would in the result, not will."},{wrong:"If I had a car, I can drive you.",right:"If I had a car, I could drive you.",why:"In an imagined result, can becomes could (= would be able to)."},{wrong:"What would you do if you will lose your job?",right:"What would you do if you lost your job?",why:"Would in the result means past simple after if: if you lost."}],ruNote:{text:"В русском «бы» стоит в обеих частях: «если бы у меня было время, я бы поехал». В английском would — только в результате, а в части с if «бы» передаёт прошедшая форма: if I had, if I knew, if I were. Прошедшая форма здесь не про прошлое, а про нереальность. Поэтому «если бы у меня было» — if I had, а не if I would have.",example:{ru:"Если бы я жил ближе, я бы чаще к тебе заходил.",en:"If I lived closer, I'd come and see you more often."}},examples:[{en:"If I had more free time, I'd learn to play the guitar.",ru:"Если бы у меня было больше свободного времени, я бы научился играть на гитаре."},{en:"If I were you, I'd ask for a pay rise.",ru:"На твоём месте я бы попросил прибавку."},{en:"What would you do if you lost your job?",ru:"Что бы ты делал, если бы потерял работу?"},{en:"If we lived by the sea, I'd swim every morning.",ru:"Если бы мы жили у моря, я бы плавал каждое утро."},{en:"If it were up to me, we'd work four days a week.",ru:"Если бы решал я, мы бы работали четыре дня в неделю."},{en:"If the flat had a balcony, we'd take it straight away.",ru:"Если бы в квартире был балкон, мы бы сразу её сняли."},{en:"If she spoke English, she could apply for that job.",ru:"Если бы она говорила по-английски, она могла бы откликнуться на эту вакансию."},{en:"It would be much easier if we had a car.",ru:"Было бы гораздо проще, если бы у нас была машина."},{en:"If I didn't have to work tomorrow, I'd stay longer.",ru:"Если бы мне не нужно было завтра на работу, я бы остался подольше."},{en:"Would you mind if I opened the window?",ru:"Вы не против, если я открою окно?"}],exercises:[{id:"sc-if-i-had",type:"choice",prompt:"If I ___ more money, I'd buy a flat in the city centre.",options:["would have","had","have","will have"],answer:1,rule:"if + past simple, would + V1 (no would after if)",explain:"The result has I'd (I would), so it is imagined: if + past simple, had. Would never goes after if.",ruHint:"«Если бы у меня было» — if I had, без would."},{id:"sc-if-i-were-you",type:"choice",prompt:"If I ___ you, I'd talk to your manager before you quit.",options:["am","would be","will be","were"],answer:3,rule:"Advice: If I were you, I'd…",explain:"For advice, use the fixed phrase If I were you, with were for every person.",ruHint:"«На твоём месте» = If I were you."},{id:"sc-quit-job",type:"collocation",prompt:"If I could afford it, I'd ___ my job and travel for a year.",options:["throw","quit","close","break"],answer:1,rule:"quit / leave your job (not throw)",explain:"«Бросить работу» is quit (or leave) your job. Throw copies «бросить» word for word: you throw a ball, not a job.",ruHint:"«Бросить работу» = quit my job."},{id:"sc-lived-closer",type:"fill",before:"If you ",after:" closer, we'd see each other more often.",answers:["lived","were living"],base:"live",rule:"Unreal now: if + past simple",explain:"You don't live close, so it is imagined: if + past simple, lived. The result already has would ('d).",ruHint:"«Если бы ты жил ближе» — if you lived."},{id:"sc-could-drive",type:"fill",before:"Sorry, I don't have a car. If I had one, I ",after:" you to the airport.",answers:["could drive"],base:"can / drive",rule:"Imagined result: can → could",explain:"The car is imaginary, so can moves back to could: I could drive you.",ruHint:"«Я мог бы отвезти» — could drive."},{id:"sc-would-drive",type:"errorTap",sentence:"Tom doesn't have a car, but if he had one, he will drive us.",wrong:11,correct:"Tom doesn't have a car, but if he had one, he would drive us.",rule:"if + past simple → would in the result",explain:"Tom has no car, so the situation is imagined: if he had one, he would drive us. Will is for a real future.",ruHint:"Если бы… — то would, а не will."},{id:"sc-won-lottery",type:"reorder",words:["what","would","you","do","if","you","won","the","lottery"],end:"?",alt:[["if","you","won","the","lottery","what","would","you","do"]],rule:"What would you do if + past simple?",explain:"An imagined situation: would in the question, past simple after if: if you won.",ruHint:"«Что бы ты сделал, если бы…» — What would you do if you + past simple."}]},{id:"third-mixed",title:"Third and mixed conditionals",summary:"A different past: if + had + V3, would have + V3 — and mixes with now.",category:"perfect",rules:[{id:"third",title:"Third conditional: a different past",steps:[{kind:"formula",parts:["If","+","had + V3","→","would have","+","V3"]},{kind:"text",text:"Use it to imagine a past that **did not happen**, and its result. It often sounds like a regret or a criticism."},{kind:"example",en:"If I had known about the party, I would have come.",ru:"Если бы я знал про вечеринку, я бы пришёл."},{kind:"tip",text:"Could have and might have also work in the result: If we'd left earlier, we **might have caught** the train."}]},{id:"short-d",title:"'d: had or would?",steps:[{kind:"text",text:"In speech, both had and would shorten to **'d**. The next word tells you which one it is."},{kind:"table",head:["'d + …","Means","Example"],rows:[["V3 (known, told)","had","If I**'d known**…"],["have + V3","would","I**'d have come**."],["V1 (come, be)","would","I**'d come**. I**'d be** happy."]]},{kind:"example",en:"If you'd told me, I'd have helped.",ru:"Если бы ты мне сказал, я бы помог."},{kind:"tip",text:"In fast speech would have sounds like **would've** /ˈwʊdəv/. Listen for it: it is the third conditional."}]},{id:"mixed",title:"Mixed: the past and the present",steps:[{kind:"table",head:["Pattern","Example"],rows:[["past if → result now: had + V3 → would + V1","If I **had studied** medicine, I **would be** a doctor now."],["true in general → past result: past simple → would have + V3","If I **were** braver, I **would have said** something."]]},{kind:"text",text:"Check the time of each half separately. If-part about the past → had + V3; result about now → would + V1. If-part true in general → past simple; result in the past → would have + V3."},{kind:"example",en:"If I hadn't missed the flight, I'd be in Rome now.",ru:"Если бы я не опоздал на самолёт, я бы сейчас был в Риме."},{kind:"tip",text:"**Now**, **today** or **still** in the result usually means would + V1."}]}],mistakes:[{wrong:"If I would have known, I would have come.",right:"If I had known, I would have come.",why:"Would never goes after if: the if-part takes had + V3."},{wrong:"If you told me earlier, I would have helped.",right:"If you had told me earlier, I would have helped.",why:"A past that didn't happen needs had + V3 after if; past simple there is for an imagined present."},{wrong:"If you had invited me to your party last Saturday, I would come.",right:"If you had invited me to your party last Saturday, I would have come.",why:"The party is over, so the result is past too: would have + V3, not would + V1."},{wrong:"If I had more time yesterday, I would finish the report.",right:"If I had had more time yesterday, I would have finished the report.",why:"Yesterday is past: have becomes had had after if, and the result is would have + V3."}],ruNote:{text:"Русское «если бы я знал» одинаково и про сейчас, и про прошлое — время понятно только из контекста. В английском это две разные конструкции: про сейчас — if I knew (второй тип), про то, что уже случилось или не случилось, — if I had known (третий тип) и would have + V3 в результате. Если причина в прошлом, а результат сейчас, части смешиваются: If I had studied medicine, I would be a doctor now.",example:{ru:"Если бы я знал, что ты в городе, я бы тебе позвонил.",en:"If I'd known you were in town, I'd have called you."}},examples:[{en:"If I'd known you were vegetarian, I'd have cooked something else.",ru:"Если бы я знал, что ты вегетарианец, я бы приготовил что-нибудь другое."},{en:"We would have missed the flight if we hadn't taken a taxi.",ru:"Мы бы опоздали на рейс, если бы не взяли такси."},{en:"If you had asked me, I would have helped you.",ru:"Если бы ты меня попросил, я бы тебе помог."},{en:"If she hadn't moved to London, she would never have met her husband.",ru:"Если бы она не переехала в Лондон, она бы никогда не встретила своего мужа."},{en:"I wouldn't have bought the flat if I'd seen the neighbours first.",ru:"Я бы не купил эту квартиру, если бы сначала увидел соседей."},{en:"If I'd saved more money, I could have travelled for a year.",ru:"Если бы я откладывал больше денег, я смог бы целый год путешествовать."},{en:"If I had taken that job, I would be living in Berlin now.",ru:"Если бы я тогда согласился на ту работу, сейчас я бы жил в Берлине."},{en:"If I hadn't spent so much last month, I wouldn't be broke now.",ru:"Если бы я не потратил столько в прошлом месяце, сейчас не сидел бы без денег."},{en:"If he were more organised, he wouldn't have missed the deadline.",ru:"Будь он организованнее, он бы не сорвал срок."},{en:"If I spoke French, I would have understood what they were saying.",ru:"Если бы я знал французский, я бы понял, о чём они говорили."}],exercises:[{id:"tm-had-known",type:"choice",prompt:"If I ___ about the traffic, I would have taken the metro.",options:["knew","had known","would know","have known"],answer:1,rule:"Unreal past: if + had + V3, would have + V3",explain:"The result is would have taken, so this is about the past: the if-part needs had + V3, had known.",ruHint:"«Если бы я знал (тогда)» — if I had known."},{id:"tm-at-home-now",type:"choice",prompt:"If I hadn't missed the last train, I ___ at home in bed right now.",options:["would have been","will be","had been","would be"],answer:3,rule:"Past if → result now: would + V1",explain:"Missing the train is past, but 'right now' makes the result present: would be. Would have been is about the past.",ruHint:"Результат сейчас (right now) — would be, а не would have been."},{id:"tm-missed-flight",type:"collocation",prompt:"If we had left ten minutes later, we would have ___ our flight.",options:["missed","lost","skipped","failed"],answer:0,rule:"miss a flight / train / bus = опоздать на",explain:"You miss a flight, a train or a bus when you arrive too late to catch it. Lose is for things you can't find; skip means you chose not to go.",ruHint:"«Опоздать на самолёт» = miss the flight."},{id:"tm-had-bought",type:"fill",before:"If we ",after:" the tickets in advance, we would have saved a lot of money.",answers:["had bought","'d bought"],base:"buy",rule:"Unreal past: if + had + V3",explain:"The result is would have saved, so the if-part is about the past too: had bought.",ruHint:"«Если бы мы купили (тогда)» — had bought."},{id:"tm-hadnt-lost",type:"fill",before:"If I ",after:" my phone, I could call a taxi now.",answers:["hadn't lost","had not lost"],base:"not / lose",rule:"Past cause → present result (mixed)",explain:"Losing the phone happened in the past, so the if-part is had + V3: hadn't lost. The result is about now: could call.",ruHint:"Потерял раньше, проблема сейчас — if I hadn't lost."},{id:"tm-had-told",type:"errorTap",sentence:"If you told me about the problem yesterday, I would have fixed it.",wrong:2,correct:"If you had told me about the problem yesterday, I would have fixed it.",rule:"Unreal past: if + had + V3, not past simple",explain:"Yesterday is past and the result is would have fixed, so the if-part needs had + V3: had told.",ruHint:"«Если бы ты вчера сказал» — had told, а не told."},{id:"tm-would-have-come",type:"reorder",words:["I","would","have","come","if","I","had","known"],alt:[["if","I","had","known","I","would","have","come"]],rule:"would have + V3 … if + had + V3",explain:"Third conditional: would have + V3 in the result, had + V3 after if. Either half can go first.",ruHint:"«Я бы пришёл, если бы знал» — I would have come if I had known."}]},{id:"wish",title:"Wish and if only",summary:"Regrets and wishes: past simple for now, had + V3 for the past, would for others.",category:"conditionals",rules:[{id:"wish-now",title:"Wish about now: one step back",steps:[{kind:"formula",parts:["I wish","+","past simple","→","about now"]},{kind:"table",head:["Reality now","Wish"],rows:[["I don't have a car.","I wish I **had** a car."],["I can't drive.","I wish I **could** drive."],["I have to work on Saturday.","I wish I **didn't have to** work on Saturday."],["It's so cold.","I wish it **were** warmer."]]},{kind:"tip",text:"Watch the Russian «жаль, что не…»: English says what you want instead. Жаль, что я не знаю = I wish I **knew**."}]},{id:"wish-past",title:"Wish about the past: had + V3",steps:[{kind:"formula",parts:["I wish","+","had + V3","→","about the past"]},{kind:"example",en:"I wish I had studied harder at school.",ru:"Жаль, что я в школе не учился усерднее."},{kind:"example",en:"I wish I hadn't said that.",ru:"Зря я это сказал."},{kind:"tip",text:"**If only** is a stronger, more emotional wish with the same forms: If only I **knew**! If only I **had listened**!"}]},{id:"wish-would",title:"Wish + would: wanting others to change",steps:[{kind:"text",text:"Use **wish + would** when someone's behaviour (or the weather) annoys you and you want it to change."},{kind:"example",en:"I wish it would stop raining.",ru:"Хоть бы дождь уже перестал."},{kind:"table",head:["Wish about","Form","Example"],rows:[["now","past simple","I wish I **knew**."],["the past","had + V3","I wish I**'d known**."],["others' behaviour","would + V1","I wish you**'d listen**."]]},{kind:"tip",text:"Don't use wish + would about yourself: not I wish I would have more time, but I wish I **had** more time."}]}],mistakes:[{wrong:"I wish I would have a car.",right:"I wish I had a car.",why:"For your own situation now, use wish + past simple; wish + would is for other people's behaviour."},{wrong:"I wish I didn't say that.",right:"I wish I hadn't said that.",why:"Saying it is a past action, so wish takes had + V3."},{wrong:"I wish I can speak Spanish.",right:"I wish I could speak Spanish.",why:"After wish, can moves one step back to could."},{wrong:"I wish I didn't know her number.",right:"I wish I knew her number.",why:"For «жаль, что я не знаю её номер», say what you want: I wish I knew. I wish I didn't know means you'd prefer not to know."}],ruNote:{text:"«Жаль, что…» и «вот бы…» по-английски — wish, и время после него сдвигается на шаг назад: о настоящем — past simple (I wish I knew), о прошлом — past perfect (I wish I had known). Осторожно с отрицанием: в русском мы говорим, чего нет («жаль, что я не знаю»), а в английском — чего хотим (I wish I knew). Wish + would — только про других, когда раздражает их поведение: I wish you would listen.",example:{ru:"Жаль, что я не говорю по-немецки.",en:"I wish I spoke German."}},examples:[{en:"I wish I had more time for my hobbies.",ru:"Жаль, что у меня так мало времени на хобби."},{en:"I wish I could speak Spanish.",ru:"Жаль, что я не говорю по-испански."},{en:"I wish I didn't have to get up so early.",ru:"Жаль, что приходится так рано вставать."},{en:"I wish I hadn't spent so much on that phone.",ru:"Зря я потратил столько денег на этот телефон."},{en:"I wish I'd known about this earlier.",ru:"Жаль, что я не знал об этом раньше."},{en:"She wishes she had studied law instead of economics.",ru:"Она жалеет, что выбрала экономику, а не право."},{en:"I wish you'd stop checking your phone at dinner.",ru:"Перестал бы ты уже сидеть в телефоне за ужином."},{en:"I wish the neighbours would turn their music down.",ru:"Хоть бы соседи сделали музыку потише."},{en:"If only I had listened to your advice!",ru:"Эх, если бы я тогда прислушался к твоему совету!"},{en:"If only it were Friday!",ru:"Скорее бы пятница!"}],exercises:[{id:"wish-had-car",type:"choice",prompt:"I wish I ___ a car — the bus takes forever.",options:["have","would have","had","will have"],answer:2,rule:"wish + past simple = I want now to be different",explain:"You don't have a car now and want one: wish + past simple, had. Would is for other people's behaviour.",ruHint:"«Жаль, что нет машины» — I wish I had a car."},{id:"wish-would-stop",type:"choice",prompt:"I wish my flatmate ___ leaving dirty dishes in the sink.",options:["stops","will stop","is stopping","would stop"],answer:3,rule:"wish + would = I want someone else to change",explain:"You are annoyed and want another person to change their behaviour: wish + would, would stop.",ruHint:"Раздражает чужое поведение — wish + would."},{id:"wish-turn-down",type:"collocation",prompt:"I wish the neighbours would ___ their music down — it's after midnight.",options:["make","turn","put","do"],answer:1,rule:"turn the music down (not make it down)",explain:"The phrasal verb is turn down: turn the music, the TV or the heating down. 'Make it down' copies «сделать потише».",ruHint:"«Сделать музыку потише» = turn the music down."},{id:"wish-didnt-have-to",type:"fill",before:"I wish I ",after:" work this Saturday — it's my daughter's birthday.",answers:["didn't have to","did not have to"],base:"not / have to",rule:"wish + past simple, even about soon",explain:"You have to work and you don't want to. After wish, use a past form even for this Saturday: didn't have to.",ruHint:"«Жаль, что придётся работать» — I wish I didn't have to work."},{id:"wish-had-known",type:"fill",before:"I wish I ",after:" about the sale — I paid full price for this coat last week.",answers:["had known","'d known"],base:"know",rule:"wish + had + V3 = past regret",explain:"The sale and the purchase are in the past, so the regret takes past perfect: had known.",ruHint:"«Жаль, что я не знал (тогда)» — I wish I had known."},{id:"wish-went-to-bed",type:"errorTap",sentence:"I wish I went to bed earlier last night.",wrong:3,correct:"I wish I had gone to bed earlier last night.",rule:"Regret about the past: wish + had + V3",explain:"Last night is past, so wish takes past perfect: had gone. Past simple after wish is for now.",ruHint:"Жалеем о прошлом — had gone, а не went."},{id:"wish-if-only",type:"reorder",words:["if","only","I","had","listened","to","you"],end:"!",alt:[["if","I","had","only","listened","to","you"]],rule:"If only + had + V3 = strong past regret",explain:"If only is a stronger wish. About the past it takes had + V3: if only I had listened.",ruHint:"«Эх, если бы я тебя послушал!» — If only I had listened to you!"}]}],speak:[{id:"speak-if-it-rains",ru:"Если завтра будет дождь, я останусь дома.",en:["If it rains tomorrow, I'll stay at home.","If it rains tomorrow, I'll stay home.","I'll stay at home if it rains tomorrow.","I'll stay home if it rains tomorrow.","If it rains tomorrow, I'll stay in."],category:"conditionals",focus:"if + present, no will"},{id:"speak-as-soon-as-arrive",ru:"Я позвоню тебе, как только приеду.",en:["I'll call you as soon as I arrive.","I'll call you as soon as I get there.","I'll phone you as soon as I arrive.","I'll ring you as soon as I arrive.","As soon as I arrive, I'll call you.","As soon as I get there, I'll call you."],category:"conditionals",focus:"as soon as + present"},{id:"speak-unless-leave-now",ru:"Мы опоздаем, если не выйдем сейчас.",en:["We'll be late unless we leave now.","We'll be late if we don't leave now.","Unless we leave now, we'll be late.","If we don't leave now, we'll be late.","We'll be late unless we go now.","If we don't go now, we'll be late."],category:"conditionals",focus:"unless = if not"},{id:"speak-if-i-were-you",ru:"На твоём месте я бы поговорил с начальником.",en:["If I were you, I'd talk to your boss.","If I were you, I'd speak to your boss.","If I were you, I'd talk to your manager.","If I were you, I'd speak to your manager.","I'd talk to your boss if I were you.","If I were you, I'd talk to the boss."],category:"conditionals",focus:"If I were you + would"},{id:"speak-if-i-had-time",ru:"Если бы у меня было больше времени, я бы больше путешествовал.",en:["If I had more time, I'd travel more.","I'd travel more if I had more time.","If I had more free time, I'd travel more.","If I had more time, I would travel more often."],category:"conditionals",focus:"if + past simple, would"},{id:"speak-what-would-you-do",ru:"Что бы ты сделал, если бы выиграл миллион?",en:["What would you do if you won a million?","If you won a million, what would you do?","What would you do if you won a million dollars?","What would you do if you won a million pounds?","What would you do if you won a million rubles?","What would you do if you won a million roubles?"],category:"conditionals",focus:"would … if + past simple"},{id:"speak-if-youd-told-me",ru:"Если бы ты мне вчера сказал, я бы помог.",en:["If you'd told me yesterday, I'd have helped.","If you'd told me yesterday, I'd have helped you.","I'd have helped if you'd told me yesterday.","I'd have helped you if you'd told me yesterday.","If you'd told me yesterday, I could have helped."],category:"perfect",focus:"had + V3, would have + V3"},{id:"speak-missed-plane",ru:"Если бы мы тогда вышли раньше, мы бы не опоздали на самолёт.",en:["If we'd left earlier, we wouldn't have missed the plane.","If we'd left earlier, we wouldn't have missed the flight.","We wouldn't have missed the plane if we'd left earlier.","If we'd left earlier, we'd have caught the plane.","If we'd left earlier, we'd have caught the flight."],category:"perfect",focus:"third conditional, miss a flight"},{id:"speak-not-so-tired",ru:"Если бы я лёг пораньше, я бы сейчас не был таким уставшим.",en:["If I'd gone to bed earlier, I wouldn't be so tired now.","I wouldn't be so tired now if I'd gone to bed earlier.","If I'd gone to bed earlier, I wouldn't be this tired now.","If I'd gone to sleep earlier, I wouldn't be so tired now.","If I'd gone to bed earlier, I wouldn't be so tired."],category:"perfect",focus:"mixed: past cause, result now"},{id:"speak-wish-knew-number",ru:"Жаль, что я не знаю её номера.",en:["I wish I knew her number.","I wish I knew her phone number.","I wish I had her number.","If only I knew her number."],category:"conditionals",focus:"wish + past simple"},{id:"speak-wish-hadnt-said",ru:"Зря я это сказал.",en:["I wish I hadn't said that.","I wish I hadn't said it.","If only I hadn't said that.","I shouldn't have said that."],category:"conditionals",focus:"wish + had + V3"},{id:"speak-wish-stop-interrupting",ru:"Хоть бы ты перестал меня перебивать!",en:["I wish you'd stop interrupting me.","I wish you would stop interrupting me.","I wish you wouldn't interrupt me.","If only you'd stop interrupting me."],category:"conditionals",focus:"wish + would: annoyance"}],phrases:[{en:"If all goes well, …",ru:"Если всё пойдёт хорошо, …",category:"conditionals"},{en:"Let me know if you need anything.",ru:"Дай знать, если что-нибудь понадобится.",category:"conditionals"},{en:"as soon as I get there",ru:"как только доберусь",category:"conditionals"},{en:"unless you hurry",ru:"если не поторопишься",category:"conditionals"},{en:"Take a coat in case it gets cold.",ru:"Возьми куртку на случай, если похолодает.",category:"conditionals"},{en:"If I were you, I'd…",ru:"На твоём месте я бы…",category:"conditionals"},{en:"What would you do if…?",ru:"Что бы ты сделал, если бы…?",category:"conditionals"},{en:"Would you mind if I opened the window?",ru:"Вы не против, если я открою окно?",category:"conditionals"},{en:"If it were up to me, …",ru:"Если бы решал я, …",category:"conditionals"},{en:"quit your job",ru:"уйти с работы, бросить работу",category:"collocations"},{en:"If I'd known, I'd have come.",ru:"Если бы я знал, я бы пришёл.",category:"perfect"},{en:"If it hadn't been for you, …",ru:"Если бы не ты, …",category:"perfect"},{en:"miss a flight",ru:"опоздать на рейс",category:"collocations"},{en:"I wish I'd known earlier.",ru:"Жаль, что я не знал раньше.",category:"conditionals"},{en:"I wish you'd stop…",ru:"Хоть бы ты перестал…",category:"conditionals"},{en:"If only!",ru:"Если бы!",category:"conditionals"},{en:"turn the music down",ru:"сделать музыку потише",category:"collocations"}]},{number:3,title:"Verb patterns",subtitle:"Gerund or infinitive, stop/remember/try, look forward to + -ing",goal:"Choose between -ing and to + verb after common verbs and prepositions, and stop translating «хочу, чтобы» word for word.",topics:[{id:"gerund-verbs",title:"Verbs + -ing: three groups of five",summary:"After these fifteen verbs the next verb takes -ing, never to.",category:"verb-patterns",rules:[{id:"three-groups",title:"Fifteen verbs, three groups of five",steps:[{kind:"text",text:"After these verbs the next verb takes **-ing**, never to. Learn them in three groups of five: each group has its own idea."},{kind:"formula",parts:["verb","+","-ing"]},{kind:"table",head:["Group","Verbs","Example"],rows:[["1 · everyday activities","enjoy, avoid, finish, mind, practise","I **enjoy cooking**."],["2 · saying and thinking","suggest, deny, admit, consider, imagine","He **admitted making** a mistake."],["3 · habits and self-control","keep, can't help, can't stand, give up, put off","I **keep forgetting** her name."]]},{kind:"example",en:"Have you finished packing?",ru:"Ты уже собрал вещи?"},{kind:"tip",text:"Practise is the British spelling of the verb; American English writes practice. The pattern is the same: practise **speaking**."}]},{id:"no-to",title:"Suggest, mind, consider: no to",steps:[{kind:"text",text:"Russian puts an infinitive after «предложить», «избегать», «подумывать»: «предложил поехать». That is why to slips in. After these verbs English uses **-ing** only."},{kind:"table",head:["Wrong","Right"],rows:[["He suggested to go by train.","He **suggested going** by train."],["Would you mind to wait?","Would you **mind waiting**?"],["I'm considering to move.","I'm **considering moving**."],["I avoid to drive at night.","I **avoid driving** at night."],["She denied to take the money.","She **denied taking** the money."]]},{kind:"tip",text:"Suggest can also take a full clause: I suggest **(that) we leave** early. But never suggest to go, and never suggest me to go."}]},{id:"group-three",title:"Group 3: what the phrases mean",steps:[{kind:"table",head:["Verb","Meaning","Example"],rows:[["keep","do again and again","I **keep checking** my phone."],["can't help","can't stop yourself","I **couldn't help laughing**."],["can't stand","hate","I **can't stand waiting** in queues."],["give up","stop doing for good","He **gave up smoking** last year."],["put off","postpone, delay","Don't **put off booking** your flights."]]},{kind:"example",en:"I keep putting off going to the dentist.",ru:"Я всё откладываю поход к стоматологу."},{kind:"tip",text:"Mind lives mostly in questions and negatives: Would you mind **closing** the door? I don't mind **waiting**."}]}],mistakes:[{wrong:"He suggested to go by train.",right:"He suggested going by train.",why:"Suggest takes -ing (or that + a clause), never to + verb."},{wrong:"She suggested me to call the bank.",right:"She suggested that I call the bank.",why:"Suggest has no person + to pattern: say suggested that I call, or simply suggested calling."},{wrong:"Would you mind to close the window?",right:"Would you mind closing the window?",why:"Mind is always followed by -ing."},{wrong:"I'm considering to change jobs.",right:"I'm considering changing jobs.",why:"Consider takes -ing. Two -ing forms in a row may sound odd, but they are correct here."}],ruNote:{text:"После «предложить», «избегать», «продолжать», «закончить» в русском стоит инфинитив: «предложил поехать», «избегаю ездить». Поэтому так и тянет сказать suggest to go. Но после этих пятнадцати глаголов английский требует -ing: suggest going, avoid driving, keep trying. Учите их группами по пять, как готовые сочетания.",example:{ru:"Коллега предложила встретиться после обеда.",en:"My colleague suggested meeting after lunch."}},examples:[{en:"I really enjoy working with people.",ru:"Мне очень нравится работать с людьми."},{en:"I try to avoid driving in rush hour.",ru:"Стараюсь не ездить на машине в час пик."},{en:"Would you mind waiting a few minutes?",ru:"Вы не могли бы подождать несколько минут?"},{en:"Our guide suggested taking a taxi back to the hotel.",ru:"Гид предложил вернуться в отель на такси."},{en:"The company denied selling customer data.",ru:"Компания отрицала, что продавала данные клиентов."},{en:"He finally admitted making a mistake.",ru:"В конце концов он признал, что ошибся."},{en:"We're considering moving to a bigger flat.",ru:"Мы подумываем о переезде в квартиру побольше."},{en:"I can't imagine living without the internet.",ru:"Не представляю, как можно жить без интернета."},{en:"I can't stand waiting in long queues.",ru:"Терпеть не могу стоять в длинных очередях."},{en:"I've been putting off calling the bank all week.",ru:"Я всю неделю откладываю звонок в банк."}],exercises:[{id:"gv-suggested-taking",type:"choice",prompt:"The metro was closed, so my colleague suggested ___ a taxi.",options:["to take","taking","us to take","take"],answer:1,rule:"suggest + -ing (never suggest to do)",explain:"Suggest is followed by -ing: suggested taking. It never takes to + verb, with or without a person before it.",ruHint:"«Предложил взять такси» — suggested taking, без to."},{id:"gv-mind-opening",type:"choice",prompt:"It's really hot in here. Would you mind ___ the window?",options:["to open","open","opening","opened"],answer:2,rule:"mind + -ing: Would you mind opening…?",explain:"Mind is always followed by -ing. 'Would you mind opening…?' is a polite way to ask someone to do something.",ruHint:"«Вы не против открыть окно?» — mind opening."},{id:"gv-gave-up-trying",type:"collocation",prompt:"After an hour, I gave ___ trying to fix the printer and called IT.",options:["out","off","in","up"],answer:3,rule:"give up + -ing: stop doing something",explain:"Give up means stop doing something, often because it is too hard. The verb after it takes -ing: gave up trying.",ruHint:"«Бросил попытки починить» — gave up trying."},{id:"gv-considering-going",type:"fill",before:"I'm considering ",after:" back to university next year.",answers:["going"],base:"go",rule:"consider + -ing",explain:"Consider is followed by -ing: considering going. Two -ing forms in a row are fine here.",ruHint:"«Подумываю вернуться в университет» — considering going."},{id:"gv-kept-getting-lost",type:"fill",before:"We kept ",after:" lost, so in the end we bought a paper map.",answers:["getting","on getting"],base:"get",rule:"keep + -ing = again and again",explain:"Keep + -ing means something happens again and again: we kept getting lost.",ruHint:"«Мы всё время терялись» — kept getting lost."},{id:"gv-putting-off-calling",type:"errorTap",sentence:"I've been putting off call the bank for two weeks now.",wrong:4,correct:"I've been putting off calling the bank for two weeks now.",rule:"put off + -ing = postpone",explain:"Put off means postpone, and the verb after it takes -ing: putting off calling.",ruHint:"«Откладываю звонок в банк» — putting off calling."},{id:"gv-admitted-making",type:"reorder",words:["he","admitted","making","a","mistake","with","the","budget"],rule:"admit + -ing",explain:"Admit is followed by -ing: he admitted making a mistake. 'Admitted to make' is wrong.",ruHint:"«Он признал, что ошибся с бюджетом» — admitted making a mistake."}]},{id:"infinitive-verbs",title:"Verbs + to: three more groups of five",summary:"Decisions, plans and effort take to + verb; want, ask and tell take a person + to.",category:"verb-patterns",rules:[{id:"three-groups-to",title:"Fifteen verbs + to, in three groups",steps:[{kind:"formula",parts:["verb","+","to","+","verb"]},{kind:"table",head:["Group","Verbs","Example"],rows:[["1 · decisions and promises","decide, agree, refuse, promise, offer","She **refused to sign** it."],["2 · plans and effort","manage, afford, plan, hope, expect","We can't **afford to eat** out every day."],["3 · how things look or go","seem, tend, fail, learn, pretend","He **pretended to be** busy."]]},{kind:"tip",text:"Many of these verbs point to something that comes later: you decide, plan or promise **to do** it. To points forward."},{kind:"example",en:"We managed to catch the last train.",ru:"Мы успели на последний поезд."}]},{id:"tricky-meanings",title:"Tend, fail, offer: tricky meanings",steps:[{kind:"signals",items:[{word:"seem to",use:"looks like: You **seem to know** everyone here."},{word:"tend to",use:"usually happens: Flights **tend to be** cheaper in winter."},{word:"fail to",use:"didn't do what was expected: He **failed to mention** the price."},{word:"learn to",use:"gain a skill: I **learned to drive** at thirty."},{word:"pretend to",use:"act as if: He **pretended not to see** me."}]},{kind:"table",head:["«Предложить» =","Pattern","Example"],rows:[["I'll do it myself","offer + **to**","I **offered to drive** them."],["an idea for everyone","suggest + **-ing**","I **suggested taking** a taxi."]]},{kind:"tip",text:"Tend to is a natural way to say «обычно» or «как правило» about people and things in general."}]},{id:"person-to",title:"Want you to, not want that you",steps:[{kind:"text",text:"Russian «хочу, чтобы ты…» is never **want that you…** in English. Use **want + person + to + verb**. The same pattern works after ask, tell, advise, expect and would like."},{kind:"formula",parts:["want / ask / tell","+","person","+","to","+","verb"]},{kind:"table",head:["Wrong","Right"],rows:[["I want that you call me.","I **want you to call** me."],["They want that we work on Saturday.","They **want us to work** on Saturday."],["I'd like that you meet Anna.","I'd **like you to meet** Anna."],["The doctor advised me rest.","The doctor **advised me to rest**."]]},{kind:"tip",text:"After the verb use me, him, her, us, them (not I, he, she). For a negative, put **not** before to: She told me **not to worry**."}]}],mistakes:[{wrong:"I want that you call me tomorrow.",right:"I want you to call me tomorrow.",why:"Want takes a person + to + verb, never a that-clause."},{wrong:"We can't afford going on holiday this year.",right:"We can't afford to go on holiday this year.",why:"Afford is followed by to + verb."},{wrong:"She told me don't worry.",right:"She told me not to worry.",why:"Tell + person + (not) to + verb: not goes before to."},{wrong:"I suggested to drive them to the airport.",right:"I offered to drive them to the airport.",why:"When you will do it yourself, use offer to; suggest is for ideas and takes -ing."}],ruNote:{text:"Русское «чтобы» тянет за собой that: «хочу, чтобы ты пришёл» превращается в I want that you come. Так по-английски не говорят: нужно want + кто + to + глагол — I want you to come. Так же работают ask, tell, advise, expect. И ещё ловушка: «предложить» — это offer to, если сделаете вы сами, и suggest + -ing, если это идея для всех.",example:{ru:"Я хочу, чтобы ты мне перезвонил.",en:"I want you to call me back."}},examples:[{en:"We decided to stay at home and order a pizza.",ru:"Мы решили остаться дома и заказать пиццу."},{en:"He refused to answer my question.",ru:"Он отказался отвечать на мой вопрос."},{en:"My neighbour offered to look after our cat while we're away.",ru:"Соседка предложила присмотреть за нашей кошкой, пока нас не будет."},{en:"Did you manage to get tickets?",ru:"Тебе удалось достать билеты?"},{en:"We can't afford to make the same mistake twice.",ru:"Мы не можем позволить себе дважды совершить одну и ту же ошибку."},{en:"I'm hoping to find a new job by the summer.",ru:"Надеюсь найти новую работу к лету."},{en:"The printer seems to be broken again.",ru:"Кажется, принтер опять сломался."},{en:"People tend to spend more when they pay by card.",ru:"Люди обычно тратят больше, когда платят картой."},{en:"My parents want me to come home for the weekend.",ru:"Родители хотят, чтобы я приехал домой на выходные."},{en:"The doctor advised me to take a few days off.",ru:"Врач посоветовал мне несколько дней отдохнуть."}],exercises:[{id:"inf-offered-water",type:"choice",prompt:"Our neighbour ___ to water the plants while we're on holiday.",options:["suggested","offered","considered","enjoyed"],answer:1,rule:"offer to do (I'll do it) vs suggest doing (an idea)",explain:"Only offer is followed by to + verb. The neighbour will do the job personally, so offered to water is right; suggest, consider and enjoy take -ing.",ruHint:"«Соседка предложила полить цветы» — сделает сама, значит offered to."},{id:"inf-told-not-to",type:"choice",prompt:"The doctor told me ___ so much coffee.",options:["don't drink","not drink","not to drink","to not drinking"],answer:2,rule:"tell + person + not to + verb",explain:"Tell takes a person + to + verb. For a negative, put not before to: told me not to drink.",ruHint:"«Врач сказал мне не пить столько кофе» — told me not to drink."},{id:"inf-afford-stay",type:"collocation",prompt:"We couldn't ___ to stay in the city centre, so we booked a hotel near the airport.",options:["afford","allow","let","permit"],answer:0,rule:"can't afford to do: not enough money",explain:"Not having enough money is afford: couldn't afford to stay. Allow, let and permit are about permission and need a person: allow us to stay.",ruHint:"«Не могли себе позволить» (про деньги) — couldn't afford."},{id:"inf-tend-to-work",type:"fill",before:"I tend ",after:" better in the mornings, so I do the hard tasks first.",answers:["to work"],base:"work",rule:"tend + to + verb = usually",explain:"Tend is followed by to + verb: I tend to work. It means 'this usually happens'.",ruHint:"«Мне обычно лучше работается утром» — I tend to work better."},{id:"inf-want-me-to",type:"fill",before:"My parents want ",after:" a doctor, but I'm going to study design.",answers:["me to become","me to be"],base:"I / become",rule:"want + me/him/us + to + verb",explain:"Want takes a person + to + verb. Use the object form: want me to become, not want that I become.",ruHint:"«Родители хотят, чтобы я стал врачом» — want me to become."},{id:"inf-expect-finish",type:"errorTap",sentence:"We expect finishing the project by the end of May.",wrong:2,correct:"We expect to finish the project by the end of May.",rule:"expect + to + verb",explain:"Expect is followed by to + verb: we expect to finish. It looks forward, like plan and hope.",ruHint:"«Рассчитываем закончить проект» — expect to finish."},{id:"inf-ask-her-call",type:"reorder",words:["could","you","ask","her","to","call","me","back"],end:"?",rule:"ask + person + to + verb",explain:"Ask takes a person + to + verb: ask her to call me back. Back goes after me.",ruHint:"«Попросите её мне перезвонить» — ask her to call me back."}]},{id:"change-meaning",title:"Stop, remember, try: the meaning changes",summary:"With these verbs, -ing and to + verb mean different things.",category:"verb-patterns",rules:[{id:"stop",title:"Stop: -ing ends it, to says why",steps:[{kind:"table",head:["Pattern","Meaning","Example"],rows:[["stop + -ing","the activity ends","I **stopped eating** sugar. (I don't eat it now.)"],["stop + to + verb","you stop in order to do something","I **stopped to eat**. (I took a break to eat.)"]]},{kind:"example",en:"We stopped to buy some water on the way.",ru:"По дороге мы остановились купить воды."},{kind:"tip",text:"Stop to = stop **in order to**. If «чтобы» fits in Russian, use to: остановился, чтобы покурить → stopped to smoke."}]},{id:"remember-forget",title:"Remember, forget, regret: back or ahead?",steps:[{kind:"text",text:"With these verbs, **-ing** looks back at something that already happened, and **to** looks ahead at a task."},{kind:"table",head:["Pattern","Meaning","Example"],rows:[["remember + -ing","a memory: you did it","I **remember locking** the door."],["remember + to","a task: then you do it","**Remember to lock** the door."],["forget + to","a task you didn't do","I **forgot to call** her."],["never forget + -ing","a strong memory","I'll **never forget seeing** the ocean for the first time."],["regret + -ing","sorry about the past","I **regret selling** my old car."],["regret + to","formal: sorry to say now","We **regret to inform** you that…"]]},{kind:"tip",text:"Russian «не забудь сделать» is always don't forget **to** do, or remember **to** do."}]},{id:"try",title:"Try: effort or experiment?",steps:[{kind:"table",head:["Pattern","Meaning","Example"],rows:[["try + to + verb","make an effort; it's difficult","I **tried to open** the jar, but the lid was stuck."],["try + -ing","test a possible solution","Too hot? **Try opening** the window."]]},{kind:"example",en:"If the app freezes, try restarting your phone.",ru:"Если приложение зависает, попробуй перезагрузить телефон."},{kind:"tip",text:"Russian «попробовать» covers both. Ask: is it hard to do (try to) or an idea that might help (try -ing)?"}]}],mistakes:[{wrong:"I stopped to smoke two years ago.",right:"I stopped smoking two years ago.",why:"Stop + -ing means you don't do it any more; stop to smoke means you stopped in order to smoke."},{wrong:"Don't forget locking the door when you leave.",right:"Don't forget to lock the door when you leave.",why:"A task you still have to do takes to: don't forget to lock."},{wrong:"I remember to meet him at a conference in 2019.",right:"I remember meeting him at a conference in 2019.",why:"A memory of something you did takes -ing: remember meeting."},{wrong:"I regret to buy this phone.",right:"I regret buying this phone.",why:"Regret about the past takes -ing; regret to is a formal way to give bad news."}],ruNote:{text:"В русском «бросил курить» и «остановился покурить» — разные глаголы, а в английском один stop, и смысл решает форма: stop smoking — больше не курю, stop to smoke — остановился, чтобы покурить. С remember и forget так же: -ing — воспоминание о том, что уже было, to — дело, которое ещё предстоит. Try to — «стараться» (трудно), try + -ing — «попробовать как способ».",example:{ru:"Не забудь выключить свет.",en:"Don't forget to turn off the lights."}},examples:[{en:"I stopped drinking coffee after lunch, and I sleep much better now.",ru:"Я перестал пить кофе после обеда и теперь сплю гораздо лучше."},{en:"We stopped to have lunch in a small village.",ru:"Мы остановились пообедать в маленькой деревне."},{en:"Please remember to send me the invoice.",ru:"Пожалуйста, не забудь прислать мне счёт."},{en:"I remember meeting him at a friend's wedding.",ru:"Помню, как мы с ним познакомились на свадьбе у друга."},{en:"I forgot to charge my phone, so it died by lunchtime.",ru:"Я забыл зарядить телефон, и к обеду он сел."},{en:"I'll never forget travelling across Siberia by train.",ru:"Никогда не забуду, как ехал через всю Сибирь на поезде."},{en:"I regret not learning English at school.",ru:"Жалею, что не учил английский в школе."},{en:"I tried to call you, but your phone was off.",ru:"Я пытался тебе дозвониться, но у тебя был выключен телефон."},{en:"Have you tried turning it off and on again?",ru:"А ты пробовал выключить и снова включить?"},{en:"Try adding a little lemon juice — it tastes much better.",ru:"Попробуй добавить немного лимонного сока — так гораздо вкуснее."}],exercises:[{id:"cm-stopped-smoking",type:"choice",prompt:"Which sentence means that Tom doesn't smoke any more?",options:["Tom stopped smoking.","Tom stopped to smoke.","Tom stopped for a smoke."],answer:0,rule:"stop + -ing = the activity ends",explain:"Stopped smoking means he no longer smokes. Stopped to smoke and stopped for a smoke mean he took a break in order to smoke.",ruHint:"«Бросил курить» — stopped smoking."},{id:"cm-remember-locking",type:"choice",prompt:"I'm sure the door is locked — I clearly remember ___ it.",options:["to lock","locking","lock","locked"],answer:1,rule:"remember + -ing = a memory of the past",explain:"You locked the door first and now you have the memory, so use -ing: remember locking it.",ruHint:"«Точно помню, как запирал» — remember locking."},{id:"cm-try-reading",type:"choice",prompt:"If you can't sleep, ___ reading a paper book instead of scrolling on your phone.",options:["remember","stop","avoid","try"],answer:3,rule:"try + -ing = test a possible solution",explain:"Try + -ing means 'do this and see if it helps'. It is the natural way to give a practical tip.",ruHint:"«Попробуй почитать» как способ уснуть — try reading."},{id:"cm-trying-concentrate",type:"fill",before:"Could you turn the music down? I'm trying ",after:" on this report.",answers:["to concentrate","to focus"],base:"concentrate",rule:"try + to + verb = make an effort",explain:"Here try means make an effort because something is difficult. That meaning takes to + verb: trying to concentrate.",ruHint:"«Пытаюсь сосредоточиться» — trying to concentrate."},{id:"cm-regret-not-studying",type:"fill",before:"I regret ",after:" harder at school — now I have to catch up.",answers:["not studying","not having studied"],base:"not / study",rule:"regret + -ing = sorry about the past",explain:"You are sorry about something in the past, so use -ing: regret not studying. Not goes before the -ing form.",ruHint:"«Жалею, что не учился усерднее» — regret not studying."},{id:"cm-forget-to-call",type:"errorTap",sentence:"Don't forget calling your mum — it's her birthday today.",wrong:2,correct:"Don't forget to call your mum — it's her birthday today.",rule:"don't forget + to + verb = a task to do",explain:"Calling your mum is a task you still have to do, so use to: don't forget to call.",ruHint:"«Не забудь позвонить маме» — don't forget to call."},{id:"cm-dont-remember-saying",type:"reorder",words:["I","don't","remember","saying","that","at","the","meeting"],rule:"remember + -ing = a memory",explain:"You are talking about a memory of the past, so use -ing: I don't remember saying that.",ruHint:"«Не помню, чтобы я такое говорил на встрече» — remember saying."}]},{id:"preposition-ing",title:"After a preposition: always -ing",summary:"After in, at, for, without, instead of — and the to in look forward to — use -ing.",category:"verb-patterns",rules:[{id:"prep-rule",title:"Preposition + verb = -ing",steps:[{kind:"formula",parts:["preposition","+","-ing"]},{kind:"text",text:"When a verb comes right after a preposition (in, at, on, for, of, about, without, before, after, instead of), it takes **-ing**. Never to + verb, never the bare verb."},{kind:"table",head:["Pattern","Example"],rows:[["interested in","I'm **interested in starting** my own business."],["good at","She's **good at explaining** things."],["thank you for","**Thank you for helping** me."],["insist on","He **insisted on paying** for dinner."],["succeed in","They **succeeded in getting** a loan."],["instead of","Let's walk **instead of taking** a taxi."],["before / after / without","He left **without saying** goodbye."]]},{kind:"tip",text:"Russian often uses an infinitive or «что / чтобы» here: «спасибо, что помог», «настоял на том, чтобы заплатить». English simply uses preposition + -ing."}]},{id:"to-preposition",title:"When to is a preposition",steps:[{kind:"text",text:"In a few phrases **to** is a preposition, not part of the infinitive. Then the verb after it takes -ing, just like after in or at."},{kind:"table",head:["Phrase","Example"],rows:[["look forward to","I'm **looking forward to seeing** you."],["be used to (= it's normal for me)","I'm **used to getting up** early."],["get used to (= it becomes normal)","You'll **get used to working** from home."]]},{kind:"tip",text:"Test: can a noun go after this to? I look forward to **the weekend** ✓ → so the verb takes -ing: I look forward to **seeing** you."},{kind:"example",en:"We look forward to working with you.",ru:"Будем рады работать с вами."}]},{id:"used-to",title:"Used to do or be used to doing?",steps:[{kind:"table",head:["Form","Meaning","Example"],rows:[["used to + verb","a past habit, not now","I **used to smoke**. (I don't now.)"],["be used to + -ing","it's normal for me","I'm **used to working** late."],["get used to + -ing","it's becoming normal","I'm **getting used to cooking** for myself."]]},{kind:"tip",text:"Used to for a past habit has no be: I **used to live** in Omsk, not I was used to live. Be comes in only when you mean «привык»."},{kind:"example",en:"I didn't use to like coffee, but now I drink it every day.",ru:"Раньше я не любил кофе, а теперь пью его каждый день."}]}],mistakes:[{wrong:"I look forward to see you.",right:"I look forward to seeing you.",why:"To in look forward to is a preposition, so the next verb takes -ing."},{wrong:"I'm used to get up early.",right:"I'm used to getting up early.",why:"In be used to, to is a preposition: use -ing."},{wrong:"He insisted to pay for dinner.",right:"He insisted on paying for dinner.",why:"Insist takes on + -ing, not to + verb."},{wrong:"I was used to live in Omsk.",right:"I used to live in Omsk.",why:"A past habit is used to + verb with no be; be used to means «привык»."}],ruNote:{text:"Мы привыкли, что to — частица перед глаголом, поэтому пишем look forward to see. Но в look forward to, be used to, get used to это предлог (как русское «к»), и после него, как после in, at, for, without, нужен -ing. Проверка простая: если после to можно поставить существительное (look forward to the weekend), глагол будет с -ing.",example:{ru:"С нетерпением жду встречи с вами.",en:"I'm looking forward to meeting you."}},examples:[{en:"I'm really looking forward to seeing you next week.",ru:"Очень жду встречи с тобой на следующей неделе."},{en:"She's used to working long hours.",ru:"Она привыкла много работать."},{en:"It took me a year to get used to living abroad.",ru:"Мне понадобился год, чтобы привыкнуть к жизни за границей."},{en:"We used to go camping every summer.",ru:"Раньше мы каждое лето ходили в походы."},{en:"Thanks for letting me know.",ru:"Спасибо, что предупредил."},{en:"He's very good at solving problems.",ru:"Он отлично умеет решать проблемы."},{en:"Are you interested in joining our team?",ru:"Хотите присоединиться к нашей команде?"},{en:"Read the contract carefully before signing it.",ru:"Внимательно прочитайте договор, прежде чем подписывать."},{en:"Instead of complaining, let's find a solution.",ru:"Вместо того чтобы жаловаться, давай найдём решение."},{en:"My father insisted on paying for everyone.",ru:"Отец настоял на том, чтобы заплатить за всех."}],exercises:[{id:"prep-used-to-live",type:"choice",prompt:"I ___ live in Omsk, but I moved to Kazan five years ago.",options:["am used to","used to","was used to","get used to"],answer:1,rule:"used to + verb = past habit, no be",explain:"A past situation that is no longer true takes used to + verb, with no be: I used to live. Be used to means 'be familiar with' and takes -ing.",ruHint:"«Раньше жил в Омске» — I used to live, без was."},{id:"prep-get-used-driving",type:"choice",prompt:"When I moved to London, it took me months to get used to ___ on the left.",options:["driving","drive","drove","have driven"],answer:0,rule:"get used to + -ing (to is a preposition)",explain:"In get used to, to is a preposition, so the verb takes -ing: get used to driving.",ruHint:"«Привыкнуть ездить по левой стороне» — get used to driving."},{id:"prep-succeeded-in",type:"collocation",prompt:"After three attempts, she finally succeeded ___ getting a work visa.",options:["to","at","on","in"],answer:3,rule:"succeed in + -ing",explain:"The partner of succeed is in: succeeded in getting. In everyday speech, managed to get means the same.",ruHint:"«Ей удалось получить визу» — succeeded in getting или managed to get."},{id:"prep-thanks-helping",type:"fill",before:"Thank you for ",after:" me with the move last weekend.",answers:["helping"],base:"help",rule:"for + -ing: thank you for helping",explain:"For is a preposition, so the verb after it takes -ing: thank you for helping.",ruHint:"«Спасибо, что помог с переездом» — thank you for helping."},{id:"prep-not-used-working",type:"fill",before:"I'm still not used to ",after:" in an open-plan office — it's so noisy.",answers:["working"],base:"work",rule:"be used to + -ing = be familiar with",explain:"Be used to means 'it's normal for me'. To is a preposition here, so use -ing: used to working.",ruHint:"«Ещё не привык работать в опенспейсе» — not used to working."},{id:"prep-look-forward-hearing",type:"errorTap",sentence:"I look forward to hear from you soon.",wrong:4,correct:"I look forward to hearing from you soon.",rule:"look forward to + -ing",explain:"To in look forward to is a preposition, so the verb takes -ing: hearing.",ruHint:"«Жду вашего ответа» — look forward to hearing."},{id:"prep-without-saying",type:"reorder",words:["he","left","without","saying","goodbye","to","anyone"],rule:"without + -ing",explain:"Without is a preposition, so the verb after it takes -ing: without saying goodbye.",ruHint:"«Ушёл, ни с кем не попрощавшись» — without saying goodbye."}]}],speak:[{id:"speak-suggested-train",ru:"Он предложил поехать на поезде.",en:["He suggested going by train.","He suggested taking the train.","He suggested we go by train.","He suggested that we go by train.","He suggested we take the train.","He suggested we should go by train."],category:"verb-patterns",focus:"suggest + -ing, not to"},{id:"speak-keep-forgetting",ru:"Я постоянно забываю его имя.",en:["I keep forgetting his name.","I'm always forgetting his name.","I always forget his name."],category:"verb-patterns",focus:"keep + -ing"},{id:"speak-cant-stand-queues",ru:"Терпеть не могу стоять в очередях.",en:["I can't stand waiting in queues.","I can't stand waiting in line.","I can't stand standing in queues.","I can't stand queuing.","I hate waiting in queues.","I hate waiting in line."],category:"verb-patterns",focus:"can't stand + -ing"},{id:"speak-want-you-know",ru:"Я хочу, чтобы ты знал правду.",en:["I want you to know the truth.","I'd like you to know the truth.","I would like you to know the truth."],category:"verb-patterns",focus:"want + person + to"},{id:"speak-cant-afford-car",ru:"Мы не можем позволить себе купить машину.",en:["We can't afford to buy a car.","We cannot afford to buy a car.","We can't afford a car."],category:"verb-patterns",focus:"afford + to"},{id:"speak-managed-taxi",ru:"Нам удалось поймать такси.",en:["We managed to get a taxi.","We managed to catch a taxi.","We managed to find a taxi.","We managed to grab a taxi.","We were able to get a taxi."],category:"verb-patterns",focus:"manage + to"},{id:"speak-stopped-smoking",ru:"Я бросил курить два года назад.",en:["I stopped smoking two years ago.","I gave up smoking two years ago.","I quit smoking two years ago."],category:"verb-patterns",focus:"stop + -ing = no more"},{id:"speak-dont-forget-lock",ru:"Не забудь запереть дверь.",en:["Don't forget to lock the door.","Do not forget to lock the door.","Remember to lock the door."],category:"verb-patterns",focus:"forget to = a task"},{id:"speak-dont-remember-saying",ru:"Не помню, чтобы я такое говорил.",en:["I don't remember saying that.","I don't remember saying anything like that.","I don't remember saying so."],category:"verb-patterns",focus:"remember + -ing = a memory"},{id:"speak-look-forward-hearing",ru:"С нетерпением жду вашего ответа.",en:["I look forward to hearing from you.","I'm looking forward to hearing from you.","I am looking forward to hearing from you.","We look forward to hearing from you.","I look forward to your reply."],category:"verb-patterns",focus:"look forward to + -ing"},{id:"speak-used-to-early",ru:"Я привык рано вставать.",en:["I'm used to getting up early.","I am used to getting up early.","I'm used to waking up early.","I've got used to getting up early.","I've gotten used to getting up early."],category:"verb-patterns",focus:"be used to + -ing"},{id:"speak-thanks-helping-move",ru:"Спасибо, что помог мне с переездом.",en:["Thank you for helping me with the move.","Thanks for helping me with the move.","Thank you for helping me move.","Thanks for helping me move."],category:"verb-patterns",focus:"for + -ing"}],phrases:[{en:"Would you mind waiting a moment?",ru:"Не могли бы вы немного подождать?",category:"verb-patterns"},{en:"I'd suggest taking the train.",ru:"Я бы предложил поехать на поезде.",category:"verb-patterns"},{en:"I keep forgetting.",ru:"Я всё время забываю.",category:"verb-patterns"},{en:"I can't help it.",ru:"Ничего не могу с собой поделать.",category:"verb-patterns"},{en:"I can't stand it.",ru:"Терпеть этого не могу.",category:"verb-patterns"},{en:"I keep putting it off.",ru:"Я всё время это откладываю.",category:"verb-patterns"},{en:"I can't afford it.",ru:"Я не могу себе этого позволить.",category:"verb-patterns"},{en:"I didn't manage to finish.",ru:"Я не успел закончить.",category:"verb-patterns"},{en:"I'd like you to meet Anna.",ru:"Хочу познакомить тебя с Анной.",category:"verb-patterns"},{en:"She offered to help.",ru:"Она предложила помочь.",category:"verb-patterns"},{en:"I tend to agree.",ru:"Склонен согласиться.",category:"verb-patterns"},{en:"Don't forget to let me know.",ru:"Не забудь мне сообщить.",category:"verb-patterns"},{en:"Have you tried restarting it?",ru:"Ты пробовал его перезагрузить?",category:"verb-patterns"},{en:"I regret not doing it earlier.",ru:"Жалею, что не сделал этого раньше.",category:"verb-patterns"},{en:"I'm looking forward to it.",ru:"Жду с нетерпением.",category:"verb-patterns"},{en:"I look forward to hearing from you.",ru:"Жду вашего ответа.",category:"verb-patterns"},{en:"I'm used to it.",ru:"Я к этому привык.",category:"verb-patterns"},{en:"You'll get used to it.",ru:"Ты привыкнешь.",category:"verb-patterns"},{en:"Thanks for letting me know.",ru:"Спасибо, что сообщил.",category:"verb-patterns"},{en:"without saying a word",ru:"не сказав ни слова",category:"verb-patterns"}]},{number:4,title:"Passive, reported speech, deduction",subtitle:"The passive, reporting what people said, must/might/can't have",goal:"Say what was done without naming who did it, report what people told you, and make confident guesses about the present and the past.",topics:[{id:"passive",title:"The passive: be + V3",summary:"When the action or the result matters more than who did it.",category:"passive-reported",rules:[{id:"be-v3-tenses",title:"Be + V3 in every tense",steps:[{kind:"text",text:"The passive is **be + V3**. Only be changes with the tense; the V3 stays the same. Use it when the action or the result matters more than who did it."},{kind:"table",head:["Tense","Passive","Example"],rows:[["present simple","am/is/are + V3","Coffee **is grown** in Brazil."],["present continuous","is/are **being** + V3","My car **is being repaired**."],["past simple","was/were + V3","This bridge **was built** in 1890."],["present perfect","has/have **been** + V3","Your order **has been sent**."],["future","will be + V3","The work **will be done** by Friday."],["modal","can/must/should be + V3","It **can be fixed** today."]]},{kind:"example",en:"The results will be announced next week.",ru:"Результаты объявят на следующей неделе."},{kind:"tip",text:"Every passive has a form of be, and the main verb is always V3: is **made**, was **made**, has been **made**, will be **made**."}]},{id:"passive-or-not",title:"Passive or not? Ask who did it",steps:[{kind:"text",text:"Use be + V3 only when someone **does the action to** the subject. If the subject does it itself, or it just happens, there is no be. This is the Day 1 rule again."},{kind:"table",head:["Wrong","Right","Why"],rows:[["The meeting is started at 9.","The meeting **starts** at 9.","a timetable: present simple"],["The meeting cancelled.","The meeting **was cancelled**.","someone cancelled it"],["The accident was happened at night.","The accident **happened** at night.","happen has no passive"],["Prices are risen.","Prices **have risen**.","rise has no object"]]},{kind:"signals",items:[{word:"no by",use:"who did it is unknown, obvious or not important"},{word:"by + person",use:"who did it is new or important: painted by Repin"}]},{kind:"tip",text:"Russian often hides the doer: «Встречу перенесли», «Мне сказали». English uses the passive: The meeting **was moved**. I **was told**."}]},{id:"it-is-said",title:"It is said that… / He is said to…",steps:[{kind:"text",text:"To pass on what people in general say, think or expect, English often uses the passive. It sounds neutral and is common in the news and at work."},{kind:"table",head:["Pattern","Example"],rows:[["It is said that + sentence","**It is said that** the company is in trouble."],["subject + is said to + verb","The company **is said to be** in trouble."],["subject + is said to have + V3","The CEO **is said to have resigned**."]]},{kind:"signals",items:[{word:"believe, think",use:"It is believed that… / He is thought to be…"},{word:"expect",use:"The new line is expected to open in May."},{word:"know, report",use:"She is known to be strict."}]},{kind:"tip",text:"In conversation, «говорят» is often just **apparently** or **people say**: Apparently, the new boss is very strict."}]}],mistakes:[{wrong:"My car is repairing at the moment.",right:"My car is being repaired at the moment.",why:"The car doesn't repair anything: someone repairs it, so use is being + V3."},{wrong:"I was said to wait here.",right:"I was told to wait here.",why:"An instruction comes from tell + person (they told me to wait), so the passive is I was told. 'I am said to…' means only 'people say that I…'."},{wrong:"This house was build in 1905.",right:"This house was built in 1905.",why:"After be the passive needs V3 (built), not the base form."},{wrong:"The accident was happened at night.",right:"The accident happened at night.",why:"Happen has no object, so it has no passive: past simple alone."}],ruNote:{text:"В русском пассив часто прячется в безличной форме на «-ли» или в глаголе на «-ся»: «встречу перенесли», «машина ремонтируется», «мне сказали». В английском это be + V3: The meeting was moved, the car is being repaired, I was told. Если действие совершают над подлежащим — нужен пассив; если оно происходит само (happen, rise, start по расписанию) — be не нужен.",example:{ru:"Мне сказали, что заказ уже отправили.",en:"I was told that the order had already been sent."}},examples:[{en:"The documents will be signed on Monday.",ru:"Документы подпишут в понедельник."},{en:"All our orders are checked before they're sent.",ru:"Все заказы проверяют перед отправкой."},{en:"The road outside our office is being repaired, so it's very noisy.",ru:"Дорогу у нашего офиса ремонтируют, поэтому очень шумно."},{en:"I was told to wait at reception.",ru:"Мне сказали подождать на ресепшене."},{en:"Breakfast is served from seven to ten.",ru:"Завтрак подают с семи до десяти."},{en:"The problem can't be fixed without a new part.",ru:"Без новой детали проблему не решить."},{en:"All the tickets had been sold by the time we got there.",ru:"К тому времени, как мы пришли, все билеты уже были проданы."},{en:"The new manager is said to be very demanding.",ru:"Говорят, новый руководитель очень требовательный."},{en:"Were you invited to the wedding?",ru:"Тебя пригласили на свадьбу?"},{en:"This photo was taken by my grandfather in 1965.",ru:"Это фото сделал мой дедушка в 1965 году."}],exercises:[{id:"pas-kitchen-renovated",type:"choice",prompt:"Sorry about the noise — our kitchen ___ at the moment.",options:["is renovating","renovates","is being renovated","has renovated"],answer:2,rule:"Passive, in progress now → is being + V3",explain:"The kitchen doesn't renovate anything: workers are renovating it right now. Present continuous passive: is being renovated.",ruHint:"«Кухню сейчас ремонтируют» — is being renovated."},{id:"pas-accident-happened",type:"choice",prompt:"The accident ___ late at night, so there were no witnesses.",options:["was happened","happened","is happened","has been happened"],answer:1,rule:"happen has no object → no passive, no be",explain:"Nobody 'happens' an accident: it happens by itself. Verbs with no object, like happen, arrive and rise, have no passive.",ruHint:"happen не бывает в пассиве: просто happened."},{id:"pas-mistakes-made",type:"collocation",prompt:"A few mistakes were ___ in the report, but they've been corrected.",options:["made","done","taken","given"],answer:0,rule:"make a mistake → mistakes were made",explain:"In English you make a mistake, so the passive is mistakes were made. 'Do a mistake' is a copy of «сделать ошибку».",ruHint:"«Сделать ошибку» — make a mistake, в пассиве were made."},{id:"pas-parcel-sent",type:"fill",before:"Good news: your parcel ",after:" and should arrive tomorrow.",answers:["has just been sent","'s just been sent","was just sent"],base:"just / send",rule:"Present perfect passive: has been + V3",explain:"Someone sent the parcel, and the result matters now: has just been sent. Just goes after has.",ruHint:"«Посылку только что отправили» — has just been sent."},{id:"pas-said-to-be",type:"fill",before:"The new Georgian restaurant near our office ",after:" excellent. Shall we try it?",answers:["is said to be"],base:"say / be",rule:"be said to + verb = people say that…",explain:"To pass on what people say, use is said to + verb: it is said to be excellent = people say it is excellent.",ruHint:"«Говорят, он отличный» — is said to be excellent."},{id:"pas-car-being-repaired",type:"errorTap",sentence:"My car is repairing at the moment, so I'm taking the bus.",wrong:3,correct:"My car is being repaired at the moment, so I'm taking the bus.",rule:"Someone repairs it now → is being + V3",explain:"The car doesn't repair anything: a mechanic repairs it. Present continuous passive: is being repaired.",ruHint:"«Машина ремонтируется» — is being repaired, а не is repairing."},{id:"pas-contract-signed",type:"reorder",words:["the","contract","must","be","signed","by","both","sides"],rule:"Modal passive: must be + V3; by + who does it",explain:"After a modal comes be + V3: must be signed. By both sides is useful here because it says who must sign.",ruHint:"«Договор должны подписать обе стороны» — must be signed by."}]},{id:"reported-speech",title:"Reported speech",summary:"Pass on what people said and asked: one step back in time, statement word order.",category:"passive-reported",rules:[{id:"one-step-back",title:"One step back in time",steps:[{kind:"text",text:"When the reporting verb is in the past (said, told, asked), the verb in the report usually moves **one step back** in time."},{kind:"table",head:["They said","You report"],rows:[["I **am** tired.","She said she **was** tired."],["I **work** from home.","He said he **worked** from home."],["We'**re leaving**.","They said they **were leaving**."],["I'**ve finished**.","She said she **had finished**."],["I **sent** it.","He said he **had sent** it."],["I'**ll call** you.","He said he **would call** me."],["I **can** help.","She said she **could** help."]]},{kind:"signals",items:[{word:"tomorrow",use:"→ the next day / the following day"},{word:"yesterday",use:"→ the day before / the previous day"},{word:"next week",use:"→ the following week"},{word:"two days ago",use:"→ two days before"},{word:"today, now",use:"→ that day, then"},{word:"here, this",use:"→ there, that"}]},{kind:"tip",text:"Change tenses and time words only when the situation has changed. Still true? Keep it: He said he **lives** in Kazan. Reporting the same day? He said he'd call **tomorrow** is fine."}]},{id:"say-tell-verbs",title:"Say, tell and other reporting verbs",steps:[{kind:"table",head:["say","tell"],rows:[["say (that)…: He **said** it was late.","tell + person: He **told me** it was late."],["say something **to** someone: She **said** goodbye **to** us.","tell + person + to: She **told me to** wait."],["not: He said me…","not: He told that…"]]},{kind:"tip",text:"Tell needs a person straight after it: told **me**, told **the team**. Say never does. Fixed phrases are the exception: tell the truth, tell a lie, tell a joke."},{kind:"table",head:["Verb","Pattern","Example"],rows:[["suggest","+ -ing / + that we…","She **suggested taking** a taxi."],["deny, admit","+ -ing","He **denied taking** the money."],["promise, offer, refuse","+ to + verb","They **promised to call** back."],["advise, remind, warn","+ person + to + verb","He **advised me to wait**."]]},{kind:"tip",text:"These are the Day 3 verb patterns. Never 'suggested me to': say **suggested taking** or **suggested (that) I take**."}]},{id:"reported-questions",title:"Reported questions",steps:[{kind:"text",text:"A reported question is not a question any more: use **statement word order** (subject + verb), **no do/does/did** and no question mark."},{kind:"table",head:["Question","Reported"],rows:[["Where **do you live**?","She asked where **I lived**."],["What time **does it start**?","He asked what time **it started**."],["**Are you** free on Friday?","She asked **if I was** free on Friday."],["**Can you** help me?","He asked **whether I could** help him."]]},{kind:"formula",parts:["asked","+","if / whether","+","subject","+","verb"]},{kind:"tip",text:"Polite questions work the same way: Could you tell me where **the station is**? (not where is the station)"}]}],mistakes:[{wrong:"He said me that he was busy.",right:"He told me that he was busy.",why:"Tell takes a person straight after it; say does not."},{wrong:"She asked me where do I live.",right:"She asked me where I lived.",why:"A reported question has statement word order and no do."},{wrong:"He asked me did I like the hotel.",right:"He asked me if I liked the hotel.",why:"A yes/no question is reported with if or whether + statement word order."},{wrong:"He suggested me to take a taxi.",right:"He suggested taking a taxi.",why:"Suggest takes -ing or that…, never person + to, even though Russian says «предложил мне»."}],ruNote:{text:"В русском косвенная речь сохраняет время прямой: «Он сказал, что занят», «Она спросила, где я живу». В английском после said или asked время обычно сдвигается на шаг назад: He said he was busy. She asked where I lived. В косвенном вопросе порядок слов как в утверждении и нет do, а частицу «ли» передают if или whether.",example:{ru:"Он спросил, смогу ли я прийти в пятницу.",en:"He asked if I could come on Friday."}},examples:[{en:"My manager told me the deadline had been moved.",ru:"Начальник сказал мне, что дедлайн перенесли."},{en:"He said he would send the contract by Friday.",ru:"Он сказал, что пришлёт договор к пятнице."},{en:"The landlord asked how long we were planning to stay.",ru:"Хозяин квартиры спросил, на сколько мы планируем остаться."},{en:"She asked me if I had ever been to Georgia.",ru:"Она спросила, был ли я когда-нибудь в Грузии."},{en:"I told him not to worry about the money.",ru:"Я сказал ему не переживать из-за денег."},{en:"They promised to call back within an hour.",ru:"Они пообещали перезвонить в течение часа."},{en:"My doctor advised me to take a few days off.",ru:"Врач посоветовал мне взять несколько выходных."},{en:"He denied breaking the printer, but nobody believed him.",ru:"Он отрицал, что сломал принтер, но ему никто не поверил."},{en:"Anna suggested meeting at the café near the station.",ru:"Анна предложила встретиться в кафе у вокзала."},{en:"Could you tell me where the nearest pharmacy is?",ru:"Не подскажете, где ближайшая аптека?"}],exercises:[{id:"rep-told-me",type:"choice",prompt:"My colleague ___ me that the meeting had been moved to Friday.",options:["said","told","spoke","explained"],answer:1,rule:"tell + person; say / explain + no person",explain:"Only tell takes a person straight after it: told me. Say, speak and explain need to before a person.",ruHint:"«Сказал мне» — told me, а не said me или explained me."},{id:"rep-suggested-visiting",type:"choice",prompt:"Our guide suggested ___ the museum early to avoid the queues.",options:["to visit","us to visit","visiting","visit"],answer:2,rule:"suggest + -ing (never suggest someone to)",explain:"Suggest is followed by -ing or by that + sentence: suggested visiting. 'Suggested us to visit' is not possible.",ruHint:"suggest + -ing: suggested visiting, а не suggested us to visit."},{id:"rep-told-the-truth",type:"collocation",prompt:"He ___ the truth, but nobody believed him.",options:["said","talked","told"],answer:2,rule:"tell the truth / tell a lie (not say the truth)",explain:"The fixed phrases are tell the truth and tell a lie. 'Said the truth' is a word-for-word copy of «сказал правду».",ruHint:"«Сказать правду» = tell the truth."},{id:"rep-would-call",type:"fill",before:"He promised he ",after:" me back in ten minutes, but he never did.",answers:["would call","'d call"],base:"will / call",rule:"Reported speech: will → would",explain:"He said «I'll call you back». After a past reporting verb, will moves one step back to would: he would call.",ruHint:"will в косвенной речи после прошедшего — would."},{id:"rep-denied-taking",type:"fill",before:"He denied ",after:" the money, but the cameras showed everything.",answers:["taking","having taken","that he took","that he had taken","he took","he had taken"],base:"take",rule:"deny + -ing (like admit and suggest)",explain:"Deny is followed by -ing, just like admit and suggest: he denied taking the money.",ruHint:"deny + -ing: denied taking."},{id:"rep-how-much-cost",type:"errorTap",sentence:"He asked me how much did the tickets cost.",wrong:5,correct:"He asked me how much the tickets cost.",rule:"Reported question: statement order, no did",explain:"A reported question is not a real question: no did, and the subject comes before the verb. Cost is also the past form.",ruHint:"В косвенном вопросе did не нужен: how much the tickets cost."},{id:"rep-asked-if-ready",type:"reorder",words:["the","manager","asked","me","if","I","was","ready"],rule:"asked + if + subject + verb",explain:"A reported yes/no question uses if (or whether) and statement word order: if I was ready, not if was I ready.",ruHint:"«Менеджер спросил, готов ли я» — if I was ready."}]},{id:"modal-deduction",title:"Must, might, can't: making guesses",summary:"How sure are you? Must, might and can't, about now and about the past.",category:"modals",rules:[{id:"guess-now",title:"Guessing about now",steps:[{kind:"text",text:"Must, might and can't can show **how sure you are**, based on what you see or know. About now: modal + verb."},{kind:"table",head:["How sure?","Modal","Example"],rows:[["almost sure: yes","must","He's worked all day. He **must be** tired."],["maybe","might / may / could","She's not answering. She **might be** busy."],["almost sure: no","can't","That **can't be** Anna — she's in Paris."]]},{kind:"formula",parts:["must / might / can't","+","be","+","-ing"]},{kind:"example",en:"They're not answering. They must be having lunch.",ru:"Не отвечают. Наверное, обедают."},{kind:"tip",text:"Must here is a conclusion, not a rule: He **must be** rich = I'm sure he is rich (look at his car). It doesn't mean he has to be rich."}]},{id:"guess-past",title:"Guessing about the past",steps:[{kind:"formula",parts:["must / might / could / can't","+","have","+","V3"]},{kind:"table",head:["Form","Meaning","Example"],rows:[["must have + V3","I'm almost sure it happened","The streets are wet. It **must have rained**."],["might / may / could have + V3","maybe it happened","She **might have missed** the train."],["can't / couldn't have + V3","I'm almost sure it didn't happen","He **can't have seen** us — he didn't wave."]]},{kind:"example",en:"I can't find my keys. I must have left them at the office.",ru:"Не могу найти ключи. Наверное, оставил их в офисе."},{kind:"tip",text:"After have, always V3: must have **gone** (not went), might have **seen** (not saw). In speech it sounds like must've, might've — never write 'must of'."},{kind:"tip",text:"Could have + V3 can also mean a chance you didn't take: You **could have told** me! (= Why didn't you?)"}]},{id:"from-russian",title:"From наверное to must have",steps:[{kind:"table",head:["In Russian","In English"],rows:[["Наверное, он устал. (I'm almost sure)","He **must be** tired."],["Может быть, она на встрече.","She **might be** in a meeting."],["Это не может быть он.","It **can't be** him."],["Наверное, я оставил их в такси.","I **must have left** them in the taxi."],["Может, он забыл.","He **might have forgotten**."],["Не может быть, чтобы он это сказал.","He **can't have said** that."]]},{kind:"tip",text:"For 'impossible', use **can't** or **can't have + V3**, not mustn't: mustn't means 'it is not allowed'. (Americans sometimes say must not for 'I guess not', but can't is always safe.)"},{kind:"tip",text:"If наверное only means 'probably', just say probably: He's probably tired. He probably forgot."}]}],mistakes:[{wrong:"That mustn't be true.",right:"That can't be true.",why:"For 'impossible' use can't; mustn't means 'it is not allowed'."},{wrong:"I can't find my phone. I must leave it in the taxi.",right:"I can't find my phone. I must have left it in the taxi.",why:"A guess about the past needs must have + V3; must leave sounds like an order."},{wrong:"They might be missed the bus.",right:"They might have missed the bus.",why:"A past guess is might have + V3. Might be + V3 is passive, as if someone missed them."},{wrong:"He maybe is at home.",right:"He may be at home.",why:"May be (two words) is modal + be. Maybe (one word) goes at the start: Maybe he's at home."}],ruNote:{text:"По-русски уверенность передают отдельные слова: «наверное», «должно быть», «может быть», «не может быть». В английском её несёт модальный глагол: must — почти уверен, что да; might или could — возможно; can't — почти уверен, что нет. О прошлом — тот же глагол + have + V3: must have left, can't have seen. «Не может быть» — это can't, а не mustn't: mustn't значит «нельзя».",example:{ru:"Он не отвечает — наверное, уже лёг спать.",en:"He isn't answering — he must have gone to bed."}},examples:[{en:"You've been travelling all day — you must be exhausted.",ru:"Ты весь день в дороге — наверное, совсем без сил."},{en:"Someone's at the door. It might be the courier.",ru:"Кто-то звонит в дверь. Может, это курьер."},{en:"That can't be right — I paid the bill last week.",ru:"Не может быть — я оплатил счёт на прошлой неделе."},{en:"She's not at her desk. She could be in a meeting.",ru:"Её нет на месте. Может, она на совещании."},{en:"The office is dark. Everyone must have gone home.",ru:"В офисе темно. Наверное, все уже ушли домой."},{en:"I can't find my passport. I might have left it at the hotel.",ru:"Не могу найти паспорт. Может, я оставил его в отеле."},{en:"She can't have forgotten — I reminded her this morning.",ru:"Не может быть, чтобы она забыла: я напомнил ей сегодня утром."},{en:"He must be earning a lot — he's just bought a new flat.",ru:"Он, должно быть, хорошо зарабатывает — только что купил новую квартиру."},{en:"You could have told me you were coming!",ru:"Мог бы и предупредить, что приедешь!"},{en:"Their flight might have been delayed.",ru:"Возможно, их рейс задержали."}],exercises:[{id:"ded-must-be-exhausted",type:"choice",prompt:"Tom has been working for twelve hours without a break. He ___ exhausted.",options:["can't be","must be","must to be","must being"],answer:1,rule:"Almost sure (now) → must + verb",explain:"Twelve hours without a break: you are almost sure, so use must be. Must is followed by the bare verb, never to or -ing.",ruHint:"«Наверняка устал» — must be, без to."},{id:"ded-cant-be-car",type:"choice",prompt:"That ___ Kate's car — she sold it last month.",options:["must be","might be","can't be","should be"],answer:2,rule:"Almost sure it's not true → can't",explain:"She sold the car, so you are sure it isn't hers. For 'impossible' use can't be.",ruHint:"«Не может быть, что это её машина» — can't be."},{id:"ded-might-have-left",type:"fill",before:"Anna isn't answering her phone. She ",after:" it at home.",answers:["might have left","might've left","may have left","could have left"],base:"might / leave",rule:"Maybe it happened → might have + V3",explain:"It is a guess about the past, so use might have + V3: might have left.",ruHint:"«Может, она оставила его дома» — might have left."},{id:"ded-cant-have-read",type:"fill",before:"He ",after:" my email — he's still asking the same question.",answers:["can't have read","cannot have read","couldn't have read","could not have read"],base:"can't / read",rule:"Sure it didn't happen → can't have + V3",explain:"You are almost sure he didn't read it, so use can't have + V3: can't have read.",ruHint:"«Не может быть, чтобы он прочитал» — can't have read."},{id:"ded-must-have-gone",type:"errorTap",sentence:"Her desk is empty, so she must have went home early.",wrong:8,correct:"Her desk is empty, so she must have gone home early.",rule:"must have + V3 (gone), not V2 (went)",explain:"After have you need V3: gone, not went. Must have gone = I'm almost sure she went.",ruHint:"После have — третья форма: gone, а не went."},{id:"ded-might-have-missed",type:"errorTap",sentence:"They didn't come last night. They might be missed the last train.",wrong:7,correct:"They didn't come last night. They might have missed the last train.",rule:"Past guess: might have + V3, not might be + V3",explain:"Last night is past, so the guess is might have + V3. Might be missed is passive, as if someone missed them.",ruHint:"«Может, они опоздали» — might have missed, а не might be."},{id:"ded-could-have-gone",type:"reorder",words:["where","could","she","have","gone"],end:"?",rule:"Question: wh- + could + subject + have + V3",explain:"In the question, could comes before the subject; have + V3 stays together: where could she have gone?",ruHint:"«Куда она могла деться?» — Where could she have gone?"}]}],speak:[{id:"speak-told-to-wait",ru:"Мне сказали подождать здесь.",en:["I was told to wait here.","I've been told to wait here.","I have been told to wait here.","They told me to wait here."],category:"passive-reported",focus:"I was told, not I was said"},{id:"speak-car-being-repaired",ru:"Мою машину сейчас ремонтируют.",en:["My car is being repaired at the moment.","My car's being repaired at the moment.","My car is being repaired now.","My car is being repaired right now.","My car is being fixed at the moment.","My car is being fixed now."],category:"passive-reported",focus:"is being + V3"},{id:"speak-order-sent",ru:"Ваш заказ уже отправлен.",en:["Your order has already been sent.","Your order's already been sent.","Your order has been sent already.","Your order was already sent.","Your order has already been shipped."],category:"passive-reported",focus:"has been + V3"},{id:"speak-hotel-said-to-be",ru:"Говорят, этот отель очень хороший.",en:["This hotel is said to be very good.","It is said that this hotel is very good.","It's said that this hotel is very good.","People say this hotel is very good.","They say this hotel is very good.","Apparently, this hotel is very good."],category:"passive-reported",focus:"is said to be"},{id:"speak-told-me-busy",ru:"Он сказал мне, что занят.",en:["He told me he was busy.","He told me that he was busy.","He said he was busy.","He said that he was busy.","He said to me that he was busy."],category:"passive-reported",focus:"tell + person, is → was"},{id:"speak-asked-where-lived",ru:"Она спросила, где я живу.",en:["She asked where I lived.","She asked me where I lived.","She asked where I live.","She asked me where I live."],category:"passive-reported",focus:"statement word order"},{id:"speak-asked-if-could-come",ru:"Он спросил, смогу ли я прийти.",en:["He asked if I could come.","He asked whether I could come.","He asked me if I could come.","He asked me whether I could come."],category:"passive-reported",focus:"ли → if / whether"},{id:"speak-suggested-taxi",ru:"Она предложила взять такси.",en:["She suggested taking a taxi.","She suggested getting a taxi.","She suggested that we take a taxi.","She suggested we take a taxi.","She suggested that we should take a taxi.","She suggested taking a cab."],category:"passive-reported",focus:"suggest + -ing"},{id:"speak-must-be-tired",ru:"Ты, наверное, очень устал.",en:["You must be very tired.","You must be really tired.","You must be exhausted.","You're probably very tired.","You are probably very tired."],category:"modals",focus:"must be = almost sure"},{id:"speak-might-have-missed",ru:"Может, они опоздали на поезд.",en:["They might have missed the train.","They might've missed the train.","They may have missed the train.","They could have missed the train.","Maybe they missed the train."],category:"modals",focus:"might have + V3"},{id:"speak-must-have-left-phone",ru:"Наверное, я оставил телефон в такси.",en:["I must have left my phone in the taxi.","I must've left my phone in the taxi.","I must have left my phone in the cab.","I probably left my phone in the taxi."],category:"modals",focus:"must have + V3"},{id:"speak-cant-have-seen",ru:"Не может быть, чтобы он нас видел.",en:["He can't have seen us.","He couldn't have seen us.","He cannot have seen us.","He could not have seen us."],category:"modals",focus:"can't have, not mustn't have"}],phrases:[{en:"I was told that…",ru:"Мне сказали, что…",category:"passive-reported"},{en:"It's being repaired.",ru:"Это сейчас ремонтируют.",category:"passive-reported"},{en:"Your order has been sent.",ru:"Ваш заказ отправлен.",category:"passive-reported"},{en:"Mistakes were made.",ru:"Были допущены ошибки.",category:"passive-reported"},{en:"It is said to be the best in town.",ru:"Говорят, это лучшее место в городе.",category:"passive-reported"},{en:"apparently",ru:"говорят, судя по всему",category:"passive-reported"},{en:"He told me to wait.",ru:"Он сказал мне подождать.",category:"passive-reported"},{en:"She asked if I could help.",ru:"Она спросила, смогу ли я помочь.",category:"passive-reported"},{en:"Could you tell me where the station is?",ru:"Не подскажете, где вокзал?",category:"passive-reported"},{en:"He suggested taking a taxi.",ru:"Он предложил взять такси.",category:"passive-reported"},{en:"tell the truth",ru:"говорить правду",category:"passive-reported"},{en:"He denied taking the money.",ru:"Он отрицал, что взял деньги.",category:"passive-reported"},{en:"advise someone to do something",ru:"советовать кому-то что-то сделать",category:"passive-reported"},{en:"You must be tired.",ru:"Ты, наверное, устал.",category:"modals"},{en:"You must be joking!",ru:"Да ты шутишь!",category:"modals"},{en:"That can't be right.",ru:"Не может быть, тут какая-то ошибка.",category:"modals"},{en:"I must have left it at home.",ru:"Наверное, я оставил это дома.",category:"modals"},{en:"You could have told me!",ru:"Мог бы и сказать!",category:"modals"},{en:"He can't have known.",ru:"Не может быть, чтобы он знал.",category:"modals"}]},{number:5,title:"Word partners",subtitle:"Collocations and phrasal verbs",goal:"Use natural word partners — make or do, spend or waste, put off or call off — instead of translating from Russian word for word.",topics:[{id:"make-do-take",title:"Make, do, take, have, pay",summary:"The noun picks the verb: learn each pair as one unit.",category:"collocations",rules:[{id:"make-or-do",title:"Make or do?",steps:[{kind:"text",text:"Russian «делать» has two English partners. **Make** is often about creating a result; **do** is about tasks, work and activities. But the noun decides, so learn the pair, not the verb."},{kind:"table",head:["make","do"],rows:[["make **a decision**","do **homework**"],["make **a mistake**","do **a course**"],["make **an effort**","do **business**"],["make **progress**","do **your best**"],["make **money**","do **harm**"],["make **a phone call**","do **the shopping**"]]},{kind:"example",en:"I made a few mistakes, but I did my best.",ru:"Я допустил пару ошибок, но сделал всё, что мог."},{kind:"tip",text:"Do goes with vague words: do something, do nothing, do everything you can. Make goes with plans and friends: make plans, make friends."}]},{id:"take-have-pay",title:"Take, have, pay",steps:[{kind:"table",head:["Verb","Partners","Russian"],rows:[["take","part in, a break, a risk, a photo","участвовать, сделать перерыв, рискнуть, сфотографировать"],["take place","an event happens","проходить, состояться"],["have","a rest, a look, a shower, a good time","отдохнуть, взглянуть, принять душ, хорошо провести время"],["pay","attention to, a visit, a compliment","обращать внимание на, навестить, сделать комплимент"]]},{kind:"example",en:"The conference takes place every May, and our team always takes part.",ru:"Конференция проходит каждый год в мае, и наша команда всегда в ней участвует."},{kind:"tip",text:"Take place and take part are active: The meeting **took place** on Monday. Not «was taken place» — nobody did anything to the meeting."},{kind:"tip",text:"Some pairs work with two verbs: **have** or **take** a break, a look, a rest. Have is especially British; take is common everywhere. Both are correct."}]},{id:"advice-attention",title:"Advice and attention",steps:[{kind:"signals",items:[{word:"give (someone) advice",use:"you are the one who advises"},{word:"get advice, ask for advice",use:"you want advice from someone"},{word:"take advice, follow advice",use:"you do what someone advised"},{word:"pay attention to",use:"обратить внимание на — to, not on"}]},{kind:"text",text:"Advice is uncountable: **some** advice, **a piece of** advice, never «an advice» or «advices». Take advice does not mean receive it: it means act on it."},{kind:"example",en:"I took your advice and booked the tickets early.",ru:"Я последовал твоему совету и купил билеты заранее."}]}],mistakes:[{wrong:"I did a mistake in the report.",right:"I made a mistake in the report.",why:"Mistake goes with make, even though Russian says «сделать ошибку»."},{wrong:"We need to accept a decision by Friday.",right:"We need to make a decision by Friday.",why:"«Принять решение» is make a decision; accept a decision means agree with someone else's."},{wrong:"Please pay attention on the dates.",right:"Please pay attention to the dates.",why:"The partner is to: pay attention to. On is a copy of «внимание на»."},{wrong:"The meeting was taken place in Room 5.",right:"The meeting took place in Room 5.",why:"Take place means happen. Nobody did it to the meeting, so there is no passive and no was."}],ruNote:{text:"В русском почти всё «делается»: ошибку, уроки, перерыв, выбор. В английском глагол выбирает существительное: make a mistake, do homework, take a break. Запоминайте не слово, а пару целиком. «Принять решение» — make a decision, а «обратить внимание на» — pay attention to.",example:{ru:"Давай сделаем перерыв и примем решение после обеда.",en:"Let's take a break and make a decision after lunch."}},examples:[{en:"I made a lot of mistakes in my first presentation.",ru:"На первой презентации я наделал кучу ошибок."},{en:"She's doing an online course in project management.",ru:"Она проходит онлайн-курс по управлению проектами."},{en:"We've made good progress this week.",ru:"На этой неделе мы хорошо продвинулись."},{en:"Let's take a short break and come back at three.",ru:"Давайте сделаем небольшой перерыв и вернёмся в три."},{en:"More than 200 companies took part in the fair.",ru:"В выставке приняли участие более 200 компаний."},{en:"The wedding will take place in June, by the sea.",ru:"Свадьба пройдёт в июне, на море."},{en:"Can you have a look at my CV before I send it?",ru:"Можешь взглянуть на моё резюме, прежде чем я его отправлю?"},{en:"I didn't pay attention to the price until I saw the bill.",ru:"Я не обратил внимания на цену, пока не увидел счёт."},{en:"He took a big risk when he left his job to start a business.",ru:"Он сильно рисковал, когда ушёл с работы, чтобы открыть своё дело."},{en:"A short walk won't do you any harm.",ru:"Небольшая прогулка тебе не повредит."}],exercises:[{id:"mdt-make-decision",type:"collocation",prompt:"We can't wait any longer — we need to ___ a decision today.",options:["do","make","accept","create"],answer:1,rule:"make a decision (not do or accept)",explain:"Decision goes with make. Accept a decision means agree with a decision that someone else has made.",ruHint:"«Принять решение» — make a decision, а не accept."},{id:"mdt-doing-course",type:"collocation",prompt:"This autumn I'm ___ an online course in data analysis.",options:["passing","learning","visiting","doing"],answer:3,rule:"do or take a course; pass is for exams",explain:"You do a course (take a course is also fine, especially in American English). Pass means get a good enough result: pass an exam.",ruHint:"«Прохожу курс» — I'm doing a course; pass — это «сдать экзамен»."},{id:"mdt-pay-attention-to",type:"collocation",prompt:"Please pay attention ___ the deadlines in the contract.",options:["on","at","to","for"],answer:2,rule:"pay attention to (not on)",explain:"The partner of pay attention is to. On is a word-for-word copy of «обратить внимание на».",ruHint:"«Обратить внимание на» — pay attention to."},{id:"mdt-took-part",type:"choice",prompt:"More than 300 runners ___ in the charity race last Sunday.",options:["took part","took place","were taken part","made part"],answer:0,rule:"People take part; events take place",explain:"People take part in an event; the event itself takes place. Both are active, so no was or were.",ruHint:"«Приняли участие» — took part, без were."},{id:"mdt-made-mistake",type:"fill",before:"Sorry, I ",after:" a mistake with your order — I'll fix it right away.",answers:["made","'ve made","have made"],base:"make",rule:"make a mistake (not do a mistake)",explain:"Mistake goes with make, even though Russian says «сделать ошибку». Made or have made both work here.",ruHint:"«Ошибиться» — make a mistake: I made a mistake."},{id:"mdt-doing-homework",type:"errorTap",sentence:"My son is still making his homework, so we'll be a bit late.",wrong:4,correct:"My son is still doing his homework, so we'll be a bit late.",rule:"do homework (not make homework)",explain:"Homework is a task, and tasks go with do: do your homework.",ruHint:"«Делать уроки» — do homework."},{id:"mdt-good-progress",type:"reorder",words:["we've","made","good","progress","this","month"],alt:[["this","month","we've","made","good","progress"]],rule:"make progress: uncountable, no a",explain:"Progress goes with make, and it is uncountable: good progress, not a good progress.",ruHint:"«Хорошо продвинулись» — made good progress, без a."}]},{id:"money-time-words",title:"Money and time",summary:"Earn, spend, waste, save, afford — and the partners Russian gets wrong.",category:"collocations",rules:[{id:"money-verbs",title:"Money verbs",steps:[{kind:"table",head:["Russian","English"],rows:[["зарабатывать","**earn** money, **make** money"],["получать зарплату","**get paid**, **earn** a salary"],["тратить на…","**spend** money **on** something"],["тратить впустую","**waste** money, **waste** time"],["копить, экономить","**save** money, **save** time, **save** for something"],["позволить себе","**afford**: can afford, can't afford"]]},{kind:"example",en:"We spend too much on taxis, so we're saving for a car.",ru:"Мы тратим слишком много на такси, поэтому копим на машину."},{kind:"tip",text:"Spend money **on** a thing, but spend time **doing** something: I spent the weekend painting the kitchen."},{kind:"tip",text:"«Не могу себе позволить» is **can't afford**, not «can't allow myself»: We can't afford a holiday this year."}]},{id:"time-phrases",title:"Time phrases",steps:[{kind:"signals",items:[{word:"run out of time",use:"there is no time left"},{word:"waste time",use:"use time badly"},{word:"save time",use:"need less time"},{word:"kill time",use:"fill time while you wait"},{word:"spend time",use:"+ -ing or with someone"},{word:"take time",use:"need a lot of time: Learning takes time."}]},{kind:"example",en:"We ran out of time, so we didn't discuss the budget.",ru:"Нам не хватило времени, поэтому бюджет мы так и не обсудили."},{kind:"tip",text:"The noun is **a waste of** time or money: That meeting was a complete waste of time."}]},{id:"look-alikes",title:"Look-alikes and strong partners",steps:[{kind:"table",head:["Phrase","Meaning"],rows:[["**carry out** a survey, research, an experiment","do it, conduct it (проводить)"],["**carry on** working, carry on **with** something","continue (продолжать)"],["**raise** a question, prices, money for charity","someone moves it up: raise + object"],["**rise**: Prices rose.","goes up by itself: no object"]]},{kind:"table",head:["Natural partner","Russian"],rows:[["**heavy** rain, **heavy** traffic","сильный дождь, плотное движение"],["**strong** coffee, **strong** wind","крепкий кофе, сильный ветер"],["**high** price, **high** salary","высокая цена, высокая зарплата"],["**deeply** sorry, **deeply** grateful","очень сожалею, глубоко благодарен"]]},{kind:"tip",text:"Raise is regular: raise, raised, raised. Rise is not: rise, rose, risen. Prices **have risen** (not have raised)."}]}],mistakes:[{wrong:"I spent a lot of money to trash.",right:"I wasted a lot of money.",why:"«Потратить впустую» is one verb in English: waste. Spend to trash is a word-for-word copy."},{wrong:"We can't allow ourselves a new car.",right:"We can't afford a new car.",why:"For money, «позволить себе» is afford. Allow means give permission."},{wrong:"Prices have raised again.",right:"Prices have risen again.",why:"Rise has no object: prices rise. Raise needs one: shops raise prices."},{wrong:"They carried on a survey of 500 people.",right:"They carried out a survey of 500 people.",why:"Carry out means do or conduct; carry on means continue."}],ruNote:{text:"«Тратить» по-английски — spend on (просто тратить) или waste (впустую); «spend money to trash» — дословный перевод, так не говорят. «Позволить себе» в деньгах — afford, а не allow myself. «Проводить опрос, исследование» — carry out, а carry on значит «продолжать». И цены rise сами, а raise их кто-то.",example:{ru:"Мы потратили впустую кучу времени и денег.",en:"We wasted a lot of time and money."}},examples:[{en:"She earns twice as much as I do.",ru:"Она зарабатывает вдвое больше меня."},{en:"We spend about a third of our income on rent.",ru:"Около трети дохода у нас уходит на аренду."},{en:"I wasted the whole evening trying to fix the printer.",ru:"Я потратил впустую весь вечер, пытаясь починить принтер."},{en:"Online check-in saves a lot of time.",ru:"Онлайн-регистрация экономит кучу времени."},{en:"We can't afford to eat out every day.",ru:"Мы не можем позволить себе каждый день есть в кафе."},{en:"I ran out of time and didn't answer the last question.",ru:"Мне не хватило времени, и я не ответил на последний вопрос."},{en:"We killed time at the airport by walking around the shops.",ru:"В аэропорту мы убивали время, гуляя по магазинам."},{en:"The university carried out a survey of 2,000 students.",ru:"Университет провёл опрос среди 2000 студентов."},{en:"She raised an important question at the meeting.",ru:"На встрече она подняла важный вопрос."},{en:"Heavy rain delayed our flight by three hours.",ru:"Из-за сильного дождя наш рейс задержали на три часа."}],exercises:[{id:"mt-waste-of-time",type:"collocation",prompt:"Honestly, that meeting was a complete ___ of time.",options:["waste","loss","spending","trash"],answer:0,rule:"a waste of time, a waste of money",explain:"The fixed phrase is a waste of time. Loss of time and trash are word-for-word copies from Russian.",ruHint:"«Пустая трата времени» — a waste of time."},{id:"mt-carry-out-survey",type:"collocation",prompt:"Our team carried ___ a survey of 500 customers.",options:["on","out","off","up"],answer:1,rule:"carry out = do; carry on = continue",explain:"You carry out a survey, research or an experiment. Carry on means continue.",ruHint:"«Провести опрос» — carry out a survey."},{id:"mt-heavy-rain",type:"collocation",prompt:"Our flight was delayed because of ___ rain.",options:["strong","thick","heavy","big"],answer:2,rule:"heavy rain, heavy traffic (not strong)",explain:"In English rain is heavy, not strong. The same goes for traffic: heavy traffic.",ruHint:"«Сильный дождь» — heavy rain."},{id:"mt-cant-afford",type:"choice",prompt:"This flat is lovely, but we can't ___ it — the rent is far too high.",options:["allow","spend","earn","afford"],answer:3,rule:"can't afford = not enough money for it",explain:"For money, «позволить себе» is afford. Allow means give permission.",ruHint:"«Не можем себе позволить» — can't afford."},{id:"mt-prices-risen",type:"fill",before:"Prices have ",after:" again, so we eat out less often.",answers:["risen","gone up","increased"],base:"rise",rule:"rise, rose, risen: no object",explain:"Prices go up by themselves, so use rise, and after have use V3: risen. Raised needs an object: they raised prices.",ruHint:"Цены растут сами — have risen, а не have raised."},{id:"mt-spend-on",type:"errorTap",sentence:"I spend too much money for taxis, so I'm going to buy a bike.",wrong:5,correct:"I spend too much money on taxis, so I'm going to buy a bike.",rule:"spend money on something",explain:"The partner of spend is on: spend money on taxis, on food, on rent.",ruHint:"«Тратить на» — spend on, а не for."},{id:"mt-ran-out-of-time",type:"reorder",words:["we","ran","out","of","time","in","the","exam"],alt:[["in","the","exam","we","ran","out","of","time"]],rule:"run out of + thing = none is left",explain:"Run out of means there is none left. The person is the subject: we ran out of time.",ruHint:"«Нам не хватило времени» — we ran out of time."}]},{id:"phrasal-verbs-1",title:"Phrasal verbs 1: ideas and problems",summary:"Fifteen phrasal verbs, each with the word it usually goes with.",category:"collocations",rules:[{id:"verb-plus-particle",title:"Verb + small word = new meaning",steps:[{kind:"text",text:"A phrasal verb is a verb plus a small word: up, out, off, down, over. Together they mean something new, often one Russian verb, so learn each one with its usual partner."},{kind:"table",head:["Phrasal verb + partner","Russian"],rows:[["come up with **an idea**","придумать идею"],["cut down on **sugar**","есть меньше сахара"],["put off **a meeting**","отложить встречу"],["look into **a problem**","разобраться в проблеме"],["figure out **a solution**","найти решение"],["turn down **an offer**","отказаться от предложения"],["take up **a hobby**","заняться новым хобби"],["give up **smoking**","бросить курить"]]},{kind:"example",en:"She came up with a great idea, but the boss turned it down.",ru:"Она придумала отличную идею, но начальник её отклонил."}]},{id:"seven-more",title:"Seven more",steps:[{kind:"table",head:["Phrasal verb + partner","Russian"],rows:[["run out of **milk**","молоко закончилось"],["get over **an illness**","оправиться от болезни"],["bring up **a topic**","поднять тему"],["set up **a company**","открыть, основать компанию"],["point out **a mistake**","указать на ошибку"],["carry out **a plan**","выполнить план"],["deal with **a complaint**","разобраться с жалобой"]]},{kind:"tip",text:"Opposites help: take **up** a hobby (start) ↔ give **up** a hobby (stop). Turn **down** an offer (say no), but turn **off** the light."},{kind:"example",en:"The manager dealt with my complaint in ten minutes.",ru:"Менеджер разобрался с моей жалобой за десять минут."}]},{id:"object-position",title:"Where do it and them go?",steps:[{kind:"text",text:"With many phrasal verbs a noun can go after the small word or in the middle: put off **the meeting** = put **the meeting** off. A pronoun (it, them, him) always goes in the middle."},{kind:"table",head:["Noun","Pronoun"],rows:[["turn down the offer, turn the offer down","turn **it** down (not turn down it)"],["put off the meeting, put the meeting off","put **it** off"],["figure out the answer, figure the answer out","figure **it** out"]]},{kind:"text",text:"Some verbs never split. Look into, deal with, get over and all three-word verbs (run out of, cut down on, come up with) keep the object at the end: look into **it**, deal with **them**."},{kind:"tip",text:"After give up and take up use a noun or -ing: give up **smoking**, take up **running** (not give up to smoke)."}]}],mistakes:[{wrong:"Can we put off it until Monday?",right:"Can we put it off until Monday?",why:"A pronoun goes between the verb and the small word: put it off."},{wrong:"I want to give up to smoke.",right:"I want to give up smoking.",why:"Give up is followed by -ing or a noun, never by to + verb."},{wrong:"We've run out milk.",right:"We've run out of milk.",why:"Run out needs of before the thing that is finished."},{wrong:"She turned off the job offer.",right:"She turned down the job offer.",why:"Turn down means say no; turn off is for lights and devices."}],ruNote:{text:"Многие фразовые глаголы — это один русский глагол: put off — отложить, turn down — отказаться, give up — бросить. Не переводите частицу отдельно: up, out, off меняют смысл целиком. Учите глагол сразу с партнёром: put off a meeting, turn down an offer. Местоимение ставится в середину: put it off.",example:{ru:"Давай отложим встречу до пятницы.",en:"Let's put off the meeting until Friday."}},examples:[{en:"She came up with a brilliant idea for the ad campaign.",ru:"Она придумала блестящую идею для рекламной кампании."},{en:"I'm trying to cut down on sugar.",ru:"Я стараюсь есть меньше сахара."},{en:"Can we put off the meeting until next week?",ru:"Можем отложить встречу до следующей недели?"},{en:"Our IT team is looking into the problem.",ru:"Наш IT-отдел разбирается с проблемой."},{en:"We still haven't figured out how to cut costs.",ru:"Мы так и не придумали, как сократить расходы."},{en:"He turned down a job offer in Dubai.",ru:"Он отказался от предложения о работе в Дубае."},{en:"I took up yoga last year, and I love it.",ru:"В прошлом году я занялся йогой, и мне очень нравится."},{en:"My dad gave up smoking ten years ago.",ru:"Папа бросил курить десять лет назад."},{en:"It took me two weeks to get over the flu.",ru:"Мне понадобилось две недели, чтобы оправиться от гриппа."},{en:"She set up her own company at 25.",ru:"Она открыла свою компанию в 25 лет."}],exercises:[{id:"pv1-turned-down",type:"collocation",prompt:"They offered me a job in Dubai, but I ___ it down because of my family.",options:["turned","put","let","cut"],answer:0,rule:"turn down an offer = say no to it",explain:"Turn down means refuse an offer or invitation. With a pronoun, it goes in the middle: turned it down.",ruHint:"«Отказаться от предложения» — turn it down."},{id:"pv1-come-up-with",type:"collocation",prompt:"We need to come up ___ a better name for the app.",options:["to","for","with","on"],answer:2,rule:"come up with an idea, a name, a plan",explain:"Come up with means think of something new. It always ends in with.",ruHint:"«Придумать» — come up with."},{id:"pv1-run-out-of-milk",type:"collocation",prompt:"We've run out ___ milk — can you buy some on your way home?",options:["from","of","off","with"],answer:1,rule:"run out of + the thing that is finished",explain:"Run out needs of before the thing: run out of milk, of money, of time.",ruHint:"«У нас закончилось молоко» — we've run out of milk."},{id:"pv1-get-over-flu",type:"choice",prompt:"It took me almost two weeks to ___ the flu.",options:["get on","give up","take up","get over"],answer:3,rule:"get over an illness = recover from it",explain:"Get over means recover from an illness or a bad experience. Give up means stop, take up means start.",ruHint:"«Оправиться от гриппа» — get over the flu."},{id:"pv1-give-up-smoking",type:"fill",before:"My doctor told me to give up ",after:", so I've stopped buying cigarettes.",answers:["smoking"],base:"smoke",rule:"give up + -ing (not to + verb)",explain:"After give up use -ing or a noun: give up smoking, give up sugar.",ruHint:"«Бросить курить» — give up smoking, без to."},{id:"pv1-pointed-out",type:"errorTap",sentence:"She pointed on a mistake in my report before I sent it.",wrong:2,correct:"She pointed out a mistake in my report before I sent it.",rule:"point out a mistake (not point on)",explain:"To show someone a mistake or a fact is point out. On is a copy of «указать на».",ruHint:"«Указать на ошибку» — point out a mistake."},{id:"pv1-put-it-off",type:"reorder",words:["let's","put","it","off","until","Monday"],rule:"Pronoun in the middle: put it off",explain:"With put off, a pronoun goes between the verb and off: put it off, not put off it.",ruHint:"«Давай отложим это до понедельника» — put it off."}]},{id:"phrasal-verbs-2",title:"Phrasal verbs 2: people and everyday life",summary:"Fifteen more for friends, work, plans and paperwork.",category:"collocations",rules:[{id:"people-and-plans",title:"People and plans",steps:[{kind:"table",head:["Phrasal verb + partner","Russian"],rows:[["look forward to **the weekend**","с нетерпением ждать выходных"],["catch up with **friends**","повидаться с друзьями, обменяться новостями"],["put up with **noise**","терпеть шум"],["get along with **colleagues**","ладить с коллегами"],["fall behind with **work**","отстать по работе"],["sort out **a problem**","решить, уладить проблему"],["call off **a meeting**","отменить встречу"],["fill in **a form**","заполнить анкету, бланк"]]},{kind:"example",en:"I get along well with my colleagues, but I can't put up with the noise in our office.",ru:"С коллегами я лажу, но шум в нашем офисе терпеть не могу."}]},{id:"everyday-life",title:"Everyday life",steps:[{kind:"table",head:["Phrasal verb + partner","Russian"],rows:[["find out **the truth**","узнать правду"],["hand in **an assignment**","сдать задание"],["show up **late**","прийти с опозданием"],["turn out **to be** true","оказаться правдой"],["go through **a difficult time**","переживать трудный период"],["keep up with **the news**","следить за новостями"],["back up **your files**","сделать резервную копию файлов"]]},{kind:"example",en:"The rumour turned out to be true.",ru:"Слух оказался правдой."}]},{id:"small-words",title:"Watch the small words",steps:[{kind:"text",text:"In look forward to, **to** is a preposition, so a noun or -ing follows: I'm looking forward **to seeing** you (not to see)."},{kind:"table",head:["Verb","Meaning"],rows:[["put **off** a meeting","move it to a later time (отложить)"],["call **off** a meeting","cancel it (отменить)"],["**find out** the truth","learn something new (узнать)"],["**know** the truth","already have the information (знать)"]]},{kind:"tip",text:"Fill in a form is British; Americans usually say **fill out** a form. Get along with is used everywhere; British English also says **get on with**."}]}],mistakes:[{wrong:"I'm looking forward to see you.",right:"I'm looking forward to seeing you.",why:"To here is a preposition, so the verb takes -ing."},{wrong:"I knew the truth only yesterday.",right:"I found out the truth only yesterday.",why:"«Узнать» new information is find out. Know means you already have it."},{wrong:"Please fill the form and sign it.",right:"Please fill in the form and sign it.",why:"Forms take fill in (British) or fill out (American), not fill alone."},{wrong:"I don't get along my boss.",right:"I don't get along with my boss.",why:"Get along needs with before the person."}],ruNote:{text:"«Узнать» — это find out (получить новую информацию), а know — «уже знать». «Отложить» — put off, «отменить» — call off: для коллег это очень разные новости. После look forward to идёт -ing, потому что to здесь предлог: I'm looking forward to seeing you.",example:{ru:"Я только вчера узнал правду.",en:"I only found out the truth yesterday."}},examples:[{en:"I'm really looking forward to the weekend.",ru:"Очень жду выходных."},{en:"I caught up with some old school friends at the weekend.",ru:"На выходных я повидался со старыми школьными друзьями."},{en:"I can't put up with the noise from the building site any more.",ru:"Я больше не могу терпеть шум со стройки."},{en:"She gets along well with all her colleagues.",ru:"Она хорошо ладит со всеми коллегами."},{en:"I fell behind with my work while I was ill.",ru:"Пока я болел, у меня накопилось много работы."},{en:"Don't worry, we'll sort it out.",ru:"Не волнуйся, мы всё уладим."},{en:"The match was called off because of the snow.",ru:"Матч отменили из-за снега."},{en:"The exam turned out to be easier than I expected.",ru:"Экзамен оказался легче, чем я ожидал."},{en:"They went through a difficult time after the company closed.",ru:"После закрытия компании им пришлось нелегко."},{en:"Back up your files before you update the system.",ru:"Сделайте резервную копию файлов перед обновлением системы."}],exercises:[{id:"pv2-called-off",type:"collocation",prompt:"The match was ___ off because of the snow, and it won't be replayed.",options:["called","put","turned","set"],answer:0,rule:"call off = cancel; put off = move later",explain:"The match will not happen at all, so it was called off (cancelled). Put off means moved to a later date.",ruHint:"«Отменили» — called off; «отложили» — put off."},{id:"pv2-get-along-with",type:"collocation",prompt:"I get along really well ___ my new colleagues.",options:["to","with","on","for"],answer:1,rule:"get along with someone",explain:"Get along needs with before the person. In British English you can also say get on with.",ruHint:"«Ладить с кем-то» — get along with."},{id:"pv2-fill-in-form",type:"collocation",prompt:"Please fill ___ this form and sign it at the bottom.",options:["on","up","in","at"],answer:2,rule:"fill in a form (US also: fill out)",explain:"Forms take fill in, or fill out in American English. Fill up is for a tank or a glass.",ruHint:"«Заполнить анкету» — fill in a form."},{id:"pv2-put-up-with",type:"choice",prompt:"Our neighbours are very loud, but we just have to ___ it.",options:["put up with","keep up with","catch up with","get along with"],answer:0,rule:"put up with = accept something annoying",explain:"Put up with means accept something unpleasant without complaining. Get along with is for people.",ruHint:"«Терпеть, мириться» — put up with."},{id:"pv2-looking-forward",type:"fill",before:"I'm really looking forward to ",after:" you at the conference.",answers:["seeing","meeting"],base:"see",rule:"look forward to + -ing (to is a preposition)",explain:"In look forward to, to is a preposition, so the next verb takes -ing: seeing.",ruHint:"После look forward to — -ing: seeing."},{id:"pv2-found-out",type:"errorTap",sentence:"I only knew the truth yesterday, when I read his email.",wrong:2,correct:"I only found out the truth yesterday, when I read his email.",rule:"find out = learn something new",explain:"Getting new information is find out. Know means you already have the information.",ruHint:"«Узнал» впервые — found out, а не knew."},{id:"pv2-turned-out",type:"reorder",words:["it","turned","out","to","be","a","great","idea"],rule:"turn out to be = be in the end",explain:"Turn out to be says what something really was in the end: it turned out to be a great idea.",ruHint:"«Это оказалось отличной идеей» — it turned out to be a great idea."}]}],speak:[{id:"speak-made-mistake",ru:"Я допустил ошибку в отчёте.",en:["I made a mistake in the report.","I've made a mistake in the report.","I have made a mistake in the report.","I made a mistake in my report.","I've made a mistake in my report."],category:"collocations",focus:"make a mistake"},{id:"speak-make-decision",ru:"Нам нужно принять решение сегодня.",en:["We need to make a decision today.","We have to make a decision today.","We need to decide today.","We need to take a decision today.","Today we need to make a decision."],category:"collocations",focus:"make a decision"},{id:"speak-take-break",ru:"Давай сделаем перерыв.",en:["Let's take a break.","Let's have a break."],category:"collocations",focus:"take a break"},{id:"speak-wasted-money",ru:"Я потратил впустую кучу денег.",en:["I wasted a lot of money.","I've wasted a lot of money.","I have wasted a lot of money.","I wasted so much money.","I wasted loads of money."],category:"collocations",focus:"waste money"},{id:"speak-cant-afford",ru:"Мы не можем себе это позволить.",en:["We can't afford it.","We cannot afford it.","We can't afford that.","We can't afford this."],category:"collocations",focus:"can't afford"},{id:"speak-run-out-of-time",ru:"У нас закончилось время.",en:["We've run out of time.","We have run out of time.","We ran out of time.","We're out of time."],category:"collocations",focus:"run out of time"},{id:"speak-put-off-meeting",ru:"Давай отложим встречу.",en:["Let's put off the meeting.","Let's put the meeting off.","Let's postpone the meeting."],category:"collocations",focus:"put off a meeting"},{id:"speak-gave-up-smoking",ru:"Он бросил курить.",en:["He gave up smoking.","He's given up smoking.","He has given up smoking.","He quit smoking.","He stopped smoking."],category:"collocations",focus:"give up + -ing"},{id:"speak-turned-down-offer",ru:"Она отказалась от предложения.",en:["She turned down the offer.","She turned the offer down.","She declined the offer.","She refused the offer."],category:"collocations",focus:"turn down an offer"},{id:"speak-looking-forward",ru:"Очень жду выходных.",en:["I'm really looking forward to the weekend.","I am really looking forward to the weekend.","I'm looking forward to the weekend.","I can't wait for the weekend.","I really can't wait for the weekend."],category:"collocations",focus:"look forward to"},{id:"speak-found-out-truth",ru:"Вчера я узнал правду.",en:["I found out the truth yesterday.","Yesterday I found out the truth.","I found the truth out yesterday.","I learned the truth yesterday.","I learnt the truth yesterday."],category:"collocations",focus:"find out, not know"},{id:"speak-match-called-off",ru:"Матч отменили.",en:["The match was called off.","The match has been called off.","They called off the match.","They called the match off.","The match was cancelled.","The match was canceled."],category:"collocations",focus:"call off = cancel"}],phrases:[{en:"come up with an idea",ru:"придумать идею",category:"collocations"},{en:"cut down on sugar",ru:"есть меньше сахара",category:"collocations"},{en:"put off a meeting",ru:"отложить встречу",category:"collocations"},{en:"look into a problem",ru:"разобраться в проблеме",category:"collocations"},{en:"figure out a solution",ru:"найти решение",category:"collocations"},{en:"turn down an offer",ru:"отказаться от предложения",category:"collocations"},{en:"take up a hobby",ru:"заняться новым хобби",category:"collocations"},{en:"give up smoking",ru:"бросить курить",category:"collocations"},{en:"run out of milk",ru:"остаться без молока (молоко закончилось)",category:"collocations"},{en:"get over an illness",ru:"оправиться от болезни",category:"collocations"},{en:"bring up a topic",ru:"поднять тему",category:"collocations"},{en:"set up a company",ru:"открыть, основать компанию",category:"collocations"},{en:"point out a mistake",ru:"указать на ошибку",category:"collocations"},{en:"carry out a plan",ru:"выполнить план",category:"collocations"},{en:"deal with a complaint",ru:"разобраться с жалобой",category:"collocations"},{en:"look forward to the weekend",ru:"с нетерпением ждать выходных",category:"collocations"},{en:"catch up with friends",ru:"повидаться с друзьями, обменяться новостями",category:"collocations"},{en:"put up with noise",ru:"терпеть шум",category:"collocations"},{en:"get along with colleagues",ru:"ладить с коллегами",category:"collocations"},{en:"fall behind with work",ru:"отстать по работе",category:"collocations"},{en:"sort out a problem",ru:"решить, уладить проблему",category:"collocations"},{en:"call off a meeting",ru:"отменить встречу",category:"collocations"},{en:"fill in a form",ru:"заполнить анкету, бланк",category:"collocations"},{en:"find out the truth",ru:"узнать правду",category:"collocations"},{en:"hand in an assignment",ru:"сдать задание",category:"collocations"},{en:"show up late",ru:"прийти с опозданием",category:"collocations"},{en:"turn out to be true",ru:"оказаться правдой",category:"collocations"},{en:"go through a difficult time",ru:"переживать трудный период",category:"collocations"},{en:"keep up with the news",ru:"следить за новостями",category:"collocations"},{en:"back up your files",ru:"сделать резервную копию файлов",category:"collocations"}]},{number:6,title:"Linking, articles, countables",subtitle:"Linking words, a/the/no article, countable and uncountable nouns",goal:"Link ideas with although, despite and however, choose between a, the and no article, and use advice, information and news correctly.",topics:[{id:"linking",title:"Linking words",summary:"Although + clause, despite + noun or -ing; however starts a new sentence.",category:"linking",rules:[{id:"although-despite",title:"Although or despite?",steps:[{kind:"text",text:"Both mean «хотя, несмотря на». Choose by what comes next: **although / even though** + subject + verb; **despite / in spite of** + a noun or -ing. Even though is a stronger although."},{kind:"table",head:["+ subject + verb","+ noun or -ing"],rows:[["**Although** it was raining, we went out.","**Despite** the rain, we went out."],["**Even though** I was tired, I finished the report.","**In spite of** being tired, I finished the report."],["We booked it **although** it was expensive.","We booked it **despite** the price."]]},{kind:"tip",text:"No **of** after despite: despite the rain (not despite of the rain). Only **in spite of** keeps its of."},{kind:"tip",text:"Want a subject and verb after despite? Add **the fact that**: **Despite the fact that** it was raining, we went out. Not: Despite it was raining."}]},{id:"but-however-whereas",title:"But, however, whereas",steps:[{kind:"table",head:["Word","How to use it","Example"],rows:[["but","joins two parts of one sentence","The flat is small, **but** it's cheap."],["however","starts a new sentence, comma after it","The flat is small. **However**, it's cheap."],["whereas / while","compares two different facts","I'm a morning person, **whereas** my wife works best at night."]]},{kind:"tip",text:"However can't join two sentences with a comma. Put a full stop or a semicolon before it: The flat is small**;** however, it's cheap."},{kind:"example",en:"My brother spends every penny, while I save almost everything.",ru:"Мой брат тратит всё до копейки, а я почти всё откладываю."},{kind:"tip",text:"Russian «а», when it compares two people or things, is often **whereas** or **while** in English. While can also mean «пока», so in writing whereas is clearer."}]},{id:"result-purpose",title:"Adding, results, purpose",steps:[{kind:"signals",items:[{word:"moreover, furthermore, in addition",use:"one more point; formal, new sentence + comma"},{word:"therefore, as a result",use:"the result; new sentence + comma: As a result, …"},{word:"so",use:"the result inside one sentence: It was late, so we left."},{word:"to / in order to + verb",use:"purpose: I came early to get a seat."},{word:"so that + subject + verb",use:"purpose with its own subject: so that we can / could…"}]},{kind:"table",head:["Purpose + verb","Purpose + subject + verb"],rows:[["I took a taxi **to** get there on time.","I took a taxi **so that** I **could** get there on time."],["I'm saving money **in order to** buy a car.","I'm saving money **so that** I **can** buy a car."]]},{kind:"tip",text:"For a person's purpose, use **to** + verb, not for: I came to London **to learn** English (not for learn, not for learning). «Чтобы не…» → **so that** … **won't / wouldn't**, or **in order not to**."},{kind:"example",en:"The trains were cancelled. As a result, half the team worked from home.",ru:"Поезда отменили. В результате половина команды работала из дома."}]}],mistakes:[{wrong:"Despite of the rain, we went for a walk.",right:"Despite the rain, we went for a walk.",why:"Despite never takes of; only in spite of does."},{wrong:"Despite it was late, she kept working.",right:"Although it was late, she kept working.",why:"Despite needs a noun or -ing; before a subject and verb, use although (or despite the fact that)."},{wrong:"The hotel was nice, however the food was terrible.",right:"The hotel was nice. However, the food was terrible.",why:"However can't join two sentences with a comma: start a new sentence, or use but."},{wrong:"I came to London for learning English.",right:"I came to London to learn English.",why:"A person's purpose is to (or in order to) + verb, not for + -ing."}],ruNote:{text:"«Несмотря на» переводится по-разному — смотрите, что идёт дальше. Перед существительным — despite или in spite of: despite the rain. Перед целым предложением — although или despite the fact that; «despite of» и «despite it was» — ошибки. А «однако» (however) начинает новое предложение: перед ним точка, после него запятая.",example:{ru:"Несмотря на то, что было поздно, мы продолжили работать.",en:"Although it was late, we carried on working."}},examples:[{en:"Although the flight was delayed, we got to the meeting on time.",ru:"Хотя рейс задержали, мы успели на встречу."},{en:"Despite the bad weather, the concert went ahead.",ru:"Несмотря на плохую погоду, концерт состоялся."},{en:"In spite of having a cold, she came to work.",ru:"Несмотря на простуду, она пришла на работу."},{en:"Even though I'd set an alarm, I overslept.",ru:"Хотя я поставил будильник, я всё равно проспал."},{en:"The rent is quite high. However, the location is perfect.",ru:"Аренда довольно высокая. Однако расположение идеальное."},{en:"My sister loves cooking, whereas I hate it.",ru:"Моя сестра обожает готовить, а я это терпеть не могу."},{en:"The course is free. Moreover, you get a certificate at the end.",ru:"Курс бесплатный. Более того, в конце выдают сертификат."},{en:"Sales fell sharply last year. As a result, the company cut its budget.",ru:"В прошлом году продажи резко упали. В результате компания урезала бюджет."},{en:"I'm saving money so that I can travel next summer.",ru:"Я коплю деньги, чтобы следующим летом поехать путешествовать."},{en:"We left early in order to avoid the traffic.",ru:"Мы выехали пораньше, чтобы не попасть в пробки."}],exercises:[{id:"lnk-despite-traffic",type:"choice",prompt:"___ the heavy traffic, we got to the airport on time.",options:["Although","Despite","Despite of","However"],answer:1,rule:"despite + noun; although + subject + verb",explain:"'The heavy traffic' is a noun with no verb, so use despite. Although needs a subject and verb, and 'despite of' does not exist.",ruHint:"«Несмотря на пробки» — despite the traffic, без of."},{id:"lnk-whereas-beach",type:"choice",prompt:"I prefer the mountains, ___ my wife loves the beach.",options:["however","despite","whereas","moreover"],answer:2,rule:"whereas: two contrasting facts in one sentence",explain:"Whereas compares two different facts inside one sentence. However and moreover start a new sentence, and despite needs a noun.",ruHint:"Русское «а» при сравнении двух людей — whereas или while."},{id:"lnk-as-a-result",type:"choice",prompt:"The last bus had already gone. ___, we had to walk home.",options:["As a result","However","Whereas","So that"],answer:0,rule:"A result in a new sentence: As a result, …",explain:"Walking home is the result of missing the bus, so use as a result. However shows a contrast, and whereas and so that can't start a sentence like this.",ruHint:"«Поэтому, в итоге» в начале предложения — As a result,"},{id:"lnk-in-order-to",type:"collocation",prompt:"We took an earlier train in ___ to avoid the rush hour.",options:["aim","purpose","way","order"],answer:3,rule:"in order to + verb = to + verb (purpose)",explain:"The fixed phrase is 'in order to' + verb. It means the same as 'to', just a little more formal.",ruHint:"«Чтобы» + глагол = (in order) to."},{id:"lnk-the-fact-that",type:"fill",before:"Despite the ",after:" that it was raining, we went for a walk.",answers:["fact"],rule:"despite + subject + verb → despite the fact that",explain:"Despite can't go straight before a subject and verb. Add 'the fact that', or use although: Although it was raining…",ruHint:"«Несмотря на то, что» = despite the fact that."},{id:"lnk-although-delay",type:"errorTap",sentence:"Although the bad weather, the match went ahead as planned.",wrong:0,correct:"Despite the bad weather, the match went ahead as planned.",rule:"Before a noun: despite / in spite of, not although",explain:"'The bad weather' is a noun with no verb. Although needs a subject and verb; before a noun, use despite or in spite of.",ruHint:"Перед существительным — despite; although — только перед подлежащим и глаголом."},{id:"lnk-so-that",type:"reorder",words:["I","set","two","alarms","so","that","I","wouldn't","oversleep"],alt:[["so","that","I","wouldn't","oversleep","I","set","two","alarms"]],rule:"Purpose with a subject: so that + could / wouldn't",explain:"So that gives a purpose with its own subject and verb. In a past story, use could or wouldn't after it.",ruHint:"«Чтобы не проспать» — so that I wouldn't oversleep."}]},{id:"articles",title:"A, the or no article",summary:"A for one of many, the for the one we both know, no article for things in general.",category:"articles",rules:[{id:"a-or-the",title:"A/an or the?",steps:[{kind:"table",head:["a / an","the"],rows:[["one of many: I need **a** pen.","we both know which: Pass me **the** pen, please."],["first mention: I saw **a** great film.","second mention: **The** film was about Japan."],["jobs: She's **an** engineer.","the only one: **the** sun, **the** internet"],["what kind of thing: It's **an** old house.","superlatives: **the** best, **the** most expensive"]]},{kind:"text",text:"**An** goes before a vowel **sound**, not a vowel letter: **an** hour, **an** MBA, but **a** university, **a** one-way ticket."},{kind:"example",en:"I bought a jacket and a pair of jeans. The jacket was half price.",ru:"Я купил куртку и джинсы. Куртка была за полцены."},{kind:"tip",text:"After be, a job or role needs a/an: I'm **a** student. She's **a** doctor. Russian «я студент» has no article, but English does."}]},{id:"general-no-article",title:"No article: things in general",steps:[{kind:"text",text:"Plural and uncountable nouns used **in general** take no article. Add **the** only when you mean particular ones."},{kind:"table",head:["In general: no article","Particular ones: the"],rows:[["**Dogs** are loyal.","**The dogs** next door bark all night."],["**Life** isn't always fair.","**The life** of a nurse is hard."],["I love **music**.","I love **the music** in this film."],["**Coffee** keeps me awake.","**The coffee** in this café is great."]]},{kind:"tip",text:"Ask: all of them, in general? → no article. These ones, that one? → the. So: **Life** is beautiful (not The life is beautiful)."}]},{id:"places-meals-transport",title:"Places, meals, transport, music",steps:[{kind:"table",head:["What","Article","Example"],rows:[["most countries and cities","no article","Spain, Japan, Kazan, London"],["Kingdom, States, Republic, plural names","the","the UK, the USA, the Netherlands"],["mountain ranges, rivers, seas","the","the Alps, the Volga, the Black Sea"],["single mountains, lakes","no article","Mount Elbrus, Lake Baikal"],["meals","no article","have breakfast, after lunch"],["by + transport","no article","by bus, by train, by car"],["musical instruments","the","play the piano, play the guitar"]]},{kind:"tip",text:"A particular vehicle needs an article again: I came **by bus** → I came **on the** 8:15 bus. In American English, play piano (no the) is also common."},{kind:"tip",text:"No article: go to **work**, go to **bed**, at **home**. With the: go to **the** office, **the** gym, **the** cinema."}]}],mistakes:[{wrong:"I am student.",right:"I'm a student.",why:"A job or role after be needs a/an: a student, an engineer."},{wrong:"The life is beautiful.",right:"Life is beautiful.",why:"Life in general takes no article; the life means one particular life."},{wrong:"I go to work by the car.",right:"I go to work by car.",why:"By + transport takes no article: by car, by bus, by train."},{wrong:"It's most expensive hotel in the city.",right:"It's the most expensive hotel in the city.",why:"Superlatives need the: the best, the most expensive."}],ruNote:{text:"В русском артиклей нет, поэтому английские легко пропустить: «я студент» — это I'm a student, а не I am student. Проверьте себя: «какой-то, один из многих» или первое упоминание — a/an; «тот самый, понятно какой» или единственный — the; «вообще, в целом» — без артикля. Поэтому «жизнь прекрасна» — Life is beautiful, без the.",example:{ru:"Я купил книгу. Книга оказалась очень интересной.",en:"I bought a book. The book turned out to be really interesting."}},examples:[{en:"My sister is an architect, and her husband is a teacher.",ru:"Моя сестра — архитектор, а её муж — учитель."},{en:"Could you close the window, please? It's cold.",ru:"Закрой, пожалуйста, окно — холодно."},{en:"We rented a flat near the beach for a week.",ru:"Мы сняли квартиру рядом с пляжем на неделю."},{en:"It's the best coffee I've ever had.",ru:"Это лучший кофе, который я когда-либо пил."},{en:"Money doesn't always bring happiness.",ru:"Деньги не всегда приносят счастье."},{en:"Children often learn languages faster than adults.",ru:"Дети часто учат языки быстрее взрослых."},{en:"I usually have breakfast at home and lunch at work.",ru:"Обычно я завтракаю дома, а обедаю на работе."},{en:"Last winter we went skiing in the Alps.",ru:"Прошлой зимой мы катались на лыжах в Альпах."},{en:"We went to Kazan by train and came back by plane.",ru:"В Казань мы поехали на поезде, а вернулись на самолёте."},{en:"The government has raised taxes again.",ru:"Правительство снова повысило налоги."}],exercises:[{id:"art-an-engineer",type:"choice",prompt:"My brother is ___ engineer at a big oil company.",options:["a","an","the"],answer:1,rule:"Job → a/an; an before a vowel sound",explain:"Jobs take a/an: he is one of many engineers. Engineer starts with a vowel sound, so use an.",ruHint:"Профессия — всегда с a/an: an engineer."},{id:"art-life-general",type:"choice",prompt:"___ is getting more and more expensive in big cities.",options:["Life","The life","A life","Lives"],answer:0,rule:"In general → no article: life, money, people",explain:"We mean life in general, not one particular life, so there is no article. Lives is plural and would need are.",ruHint:"«Жизнь» вообще — Life, без the."},{id:"art-by-bus",type:"collocation",prompt:"I usually go to work ___ bus, but today I walked.",options:["with","by the","by","on"],answer:2,rule:"by + transport, no article: by bus, by car",explain:"With by, transport takes no article: by bus, by train, by car. With on you need the: on the bus.",ruHint:"«На автобусе» — by bus, без артикля."},{id:"art-an-mba",type:"fill",before:"She has ",after:" MBA from a university in Boston.",answers:["an"],base:"a / an / the",rule:"an before a vowel sound, not a vowel letter",explain:"MBA starts with the sound /em/, a vowel sound, so use an. University starts with /juː/, so it takes a.",ruHint:"Смотрим на звук, а не на букву: an MBA, но a university."},{id:"art-the-pizza",type:"fill",before:"I ordered a pizza and a salad, but ",after:" pizza never arrived.",answers:["the","my"],base:"a / an / the",rule:"Second mention → the",explain:"The pizza has already been mentioned, so we both know which one: the pizza.",ruHint:"Второе упоминание — уже «та самая» пицца: the."},{id:"art-the-best-decision",type:"errorTap",sentence:"It was a best decision I've made in years.",wrong:2,correct:"It was the best decision I've made in years.",rule:"Superlative → the: the best, the most …",explain:"Best is a superlative: there is only one best decision, so it takes the.",ruHint:"Превосходная степень — всегда с the: the best."},{id:"art-plays-the-piano",type:"reorder",words:["she","plays","the","piano","after","dinner"],alt:[["after","dinner","she","plays","the","piano"]],rule:"play the + instrument; meals take no article",explain:"Musical instruments take the: play the piano. Meals take no article: after dinner, for lunch.",ruHint:"Играть на инструменте — the piano; завтрак, обед, ужин — без артикля."}]},{id:"countable-uncountable",title:"Countable and uncountable nouns",summary:"Advice, information, news: no a/an, no plural, singular verb.",category:"countable",rules:[{id:"uncountable-list",title:"Uncountable in English",steps:[{kind:"text",text:"These nouns are **uncountable** in English, although many are countable in Russian (совет — советы). Uncountable means: **no a/an**, **no -s**, and a **singular verb**."},{kind:"table",head:["English","Russian","Never say"],rows:[["advice","совет, советы","an advice, advices"],["information","информация, сведения","an information, informations"],["news","новость, новости","a news, the news are"],["furniture","мебель","a furniture, furnitures"],["luggage, baggage","багаж, вещи","a luggage, luggages"],["equipment","оборудование","an equipment, equipments"],["research","исследование, исследования","a research, researches"],["homework","домашнее задание","a homework, homeworks"]]},{kind:"text",text:"Also uncountable: **knowledge, progress, feedback, assistance, accommodation**. Small exceptions: a good knowledge of English; in American English, accommodations is common."},{kind:"tip",text:"Singular verb every time: **The news is** good. The information **was** wrong. Your advice **was** really helpful."}]},{id:"how-to-count",title:"Much, many, a few, a little",steps:[{kind:"table",head:["Countable","Uncountable"],rows:[["How **many** bags?","How **much** luggage?"],["**a few** ideas (= some)","**a little** time (= some)"],["**few** ideas (= almost none)","**little** time (= almost none)"],["**a lot of** friends","**a lot of** information"],["two suitcases","two **pieces of** luggage"]]},{kind:"formula",parts:["a piece of","+","advice / information / furniture"]},{kind:"tip",text:"Other ways to count: **an item of** news, **a word of** advice, **a bit of** advice (informal)."},{kind:"tip",text:"Much sounds formal in positive sentences, so say **a lot of**: We've got a lot of time. Use much in questions and negatives: Is there **much** traffic?"}]},{id:"word-partners",title:"Assistance or an assistant?",steps:[{kind:"text",text:"Often English has an uncountable noun for the idea and a countable one for a single thing or person. Need a/an or a plural? Switch to the countable partner."},{kind:"table",head:["Uncountable (the idea)","Countable (one thing or person)"],rows:[["assistance (= help)","an assistant (a person)"],["advice","a tip, a suggestion"],["work","a job, a task"],["travel","a trip, a journey"],["accommodation","a room, a flat, a place to stay"],["feedback","a comment, a review"]]},{kind:"example",en:"My assistant can give you any assistance you need.",ru:"Мой ассистент окажет вам любую необходимую помощь."},{kind:"tip",text:"**Advice** is the noun, **advise** is the verb: I **advise** you to book early. Thanks for the **advice**."}]}],mistakes:[{wrong:"Can you give me an advice?",right:"Can you give me some advice?",why:"Advice is uncountable: no a/an. Say some advice or a piece of advice."},{wrong:"Thanks for all the informations.",right:"Thanks for all the information.",why:"Information has no plural, even when there is a lot of it."},{wrong:"The news are really good.",right:"The news is really good.",why:"News ends in -s but is uncountable, so it takes a singular verb."},{wrong:"We need an assistance with the move.",right:"We need some assistance with the move.",why:"Assistance means help and is uncountable; an assistant is a person."}],ruNote:{text:"Многие слова, которые по-русски легко ставятся во множественное число, в английском неисчисляемые: совет — советы, но advice; новость — новости, но news; информация, сведения — information. С ними нет a/an, нет окончания -s, а глагол стоит в единственном числе: The news is good. Если нужно посчитать, добавьте a piece of: a piece of advice — один совет.",example:{ru:"Спасибо за советы — они очень помогли.",en:"Thanks for the advice — it really helped."}},examples:[{en:"My manager gave me some useful advice before the interview.",ru:"Перед собеседованием начальник дал мне несколько полезных советов."},{en:"Is there any information about the delay on the website?",ru:"На сайте есть какая-нибудь информация о задержке?"},{en:"The news was a real shock to everyone.",ru:"Эта новость всех по-настоящему шокировала."},{en:"You can take one piece of hand luggage on the plane.",ru:"В самолёт можно взять одно место ручной клади."},{en:"We need to buy some new furniture for the living room.",ru:"Нам нужно купить новую мебель в гостиную."},{en:"Thanks for your feedback — it was really helpful.",ru:"Спасибо за обратную связь — она очень помогла."},{en:"I've made a lot of progress with my English this month.",ru:"За этот месяц я сильно продвинулся в английском."},{en:"There's very little time left, so let's hurry.",ru:"Времени осталось совсем мало, так что давай поторопимся."},{en:"I have a few questions about the contract.",ru:"У меня есть несколько вопросов по договору."},{en:"If you need any assistance, please call reception.",ru:"Если вам нужна помощь, позвоните, пожалуйста, на ресепшен."}],exercises:[{id:"cnt-a-little-time",type:"choice",prompt:"We've still got ___ time before the train, so let's get a coffee.",options:["a few","a little","many","few"],answer:1,rule:"a little + uncountable, a few + plural",explain:"Time here is uncountable, so use a little. A few and many go with plural nouns: a few minutes.",ruHint:"С неисчисляемыми — a little: a little time."},{id:"cnt-news-was",type:"choice",prompt:"The news ___ better than we expected, so we went out to celebrate.",options:["were","are","was","have been"],answer:2,rule:"news is uncountable → singular verb: the news was",explain:"News ends in -s but is uncountable, so it takes a singular verb: the news is, the news was.",ruHint:"news — единственное число: the news was."},{id:"cnt-do-research",type:"collocation",prompt:"Before I buy a used car, I always ___ some research online.",options:["do","make","take","give"],answer:0,rule:"do research (not make); research has no plural",explain:"In English you do research (or carry it out), never make it. Research is uncountable: some research, not researches.",ruHint:"«Провести исследование, изучить вопрос» — do research."},{id:"cnt-how-much-luggage",type:"fill",before:"How ",after:" luggage are you taking on the trip?",answers:["much"],rule:"How much + uncountable, How many + plural",explain:"Luggage is uncountable, so ask how much. For a plural noun, ask how many: how many bags.",ruHint:"luggage — неисчисляемое, поэтому how much."},{id:"cnt-assistance",type:"fill",before:"If you need any ",after:" with your bags, just ask at reception.",answers:["assistance","help"],base:"assist",rule:"assistance = help (uncountable); an assistant = a person",explain:"You need help here, not a person, so use the uncountable noun assistance. An assistant is someone who helps.",ruHint:"Помощь — assistance; помощник — an assistant."},{id:"cnt-informations",type:"errorTap",sentence:"Thanks for all the informations you sent me yesterday.",wrong:4,correct:"Thanks for all the information you sent me yesterday.",rule:"information has no plural: no -s",explain:"Information is uncountable, so it never takes -s, even when there is a lot of it.",ruHint:"«Информация, сведения» — всегда information, без -s."},{id:"cnt-piece-of-advice",type:"reorder",words:["can","I","give","you","a","piece","of","advice"],end:"?",rule:"One advice → a piece of advice",explain:"Advice is uncountable, so you can't say an advice. For one, say a piece of advice, or just some advice.",ruHint:"«Один совет» — a piece of advice."}]}],speak:[{id:"speak-despite-rain",ru:"Несмотря на дождь, мы пошли гулять.",en:["Despite the rain, we went for a walk.","In spite of the rain, we went for a walk.","We went for a walk despite the rain.","We went for a walk in spite of the rain.","Despite the rain, we went out for a walk.","Despite the rain, we went out."],category:"linking",focus:"despite + noun, no of"},{id:"speak-although-late",ru:"Хотя было поздно, она продолжала работать.",en:["Although it was late, she kept working.","Even though it was late, she kept working.","Although it was late, she carried on working.","Although it was late, she continued working.","Although it was late, she continued to work.","She kept working although it was late."],category:"linking",focus:"although + subject + verb"},{id:"speak-left-early-train",ru:"Я вышел пораньше, чтобы успеть на поезд.",en:["I left early to catch the train.","I left early in order to catch the train.","I left early so that I could catch the train.","I left early so I could catch the train.","I left earlier to catch the train.","I left home early to catch the train."],category:"linking",focus:"purpose: to / so that"},{id:"speak-however-flat",ru:"Квартира маленькая. Однако она в центре.",en:["The flat is small. However, it's in the centre.","The flat is small. However, it's in the center.","The apartment is small. However, it's in the center.","The apartment is small. However, it's in the centre.","The flat is small. However, it's in the city centre.","The apartment is small. However, it's downtown."],category:"linking",focus:"however: new sentence"},{id:"speak-sister-doctor",ru:"Моя сестра — врач.",en:["My sister is a doctor.","My sister's a doctor.","My sister works as a doctor."],category:"articles",focus:"a/an + job"},{id:"speak-money-not-everything",ru:"Деньги — это не главное.",en:["Money isn't everything.","Money is not everything.","Money's not everything.","Money isn't the most important thing.","Money is not the most important thing."],category:"articles",focus:"in general → no article"},{id:"speak-work-by-bus",ru:"Обычно я езжу на работу на автобусе.",en:["I usually go to work by bus.","I usually get to work by bus.","I usually take the bus to work.","Usually I go to work by bus.","I usually travel to work by bus.","I usually commute to work by bus."],category:"articles",focus:"by bus, go to work"},{id:"speak-best-hotel",ru:"Это лучший отель в городе.",en:["It's the best hotel in the city.","It is the best hotel in the city.","This is the best hotel in the city.","It's the best hotel in town.","This is the best hotel in town."],category:"articles",focus:"the + superlative"},{id:"speak-give-advice",ru:"Можно дать тебе совет?",en:["Can I give you some advice?","Can I give you a piece of advice?","Could I give you some advice?","May I give you some advice?","Can I give you a bit of advice?","Can I give you a word of advice?"],category:"countable",focus:"advice: no a/an"},{id:"speak-news-not-good",ru:"Новости не очень хорошие.",en:["The news isn't very good.","The news is not very good.","The news isn't great.","The news is not great.","The news isn't good.","The news is not good."],category:"countable",focus:"news + is"},{id:"speak-thanks-information",ru:"Спасибо за всю информацию.",en:["Thanks for all the information.","Thank you for all the information.","Thanks for all the info.","Thank you for all the info."],category:"countable",focus:"information: no -s"},{id:"speak-how-much-luggage",ru:"Сколько у тебя багажа?",en:["How much luggage do you have?","How much luggage have you got?","How much baggage do you have?","How much baggage have you got?","How much luggage have you got with you?"],category:"countable",focus:"how much + uncountable"}],phrases:[{en:"despite the fact that…",ru:"несмотря на то, что…",category:"linking"},{en:"in spite of the weather",ru:"несмотря на погоду",category:"linking"},{en:"even though it was late",ru:"хотя было уже поздно",category:"linking"},{en:"whereas I prefer…",ru:"а я предпочитаю…",category:"linking"},{en:"As a result, …",ru:"В результате…, в итоге…",category:"linking"},{en:"in order to save time",ru:"чтобы сэкономить время",category:"linking"},{en:"so that we can…",ru:"чтобы мы могли…",category:"linking"},{en:"She works as a nurse.",ru:"Она работает медсестрой.",category:"articles"},{en:"by bus, by train, by car",ru:"на автобусе, на поезде, на машине",category:"articles"},{en:"go to work",ru:"ходить (ездить) на работу",category:"articles"},{en:"have lunch",ru:"обедать",category:"articles"},{en:"play the guitar",ru:"играть на гитаре",category:"articles"},{en:"the best decision I've ever made",ru:"лучшее решение в моей жизни",category:"articles"},{en:"a piece of advice",ru:"(один) совет",category:"countable"},{en:"The news is good.",ru:"Новости хорошие.",category:"countable"},{en:"some useful information",ru:"полезная информация, полезные сведения",category:"countable"},{en:"How much luggage…?",ru:"Сколько багажа…?",category:"countable"},{en:"make progress",ru:"делать успехи, продвигаться",category:"countable"},{en:"do research",ru:"проводить исследование, изучать вопрос",category:"countable"},{en:"give feedback",ru:"давать обратную связь",category:"countable"}]}].map(e=>n(o.O,e,`day ${e.number}`)).sort((e,t)=>e.number-t.number),s=[{number:1,title:"The tense map",subtitle:"Be + verb, present and past, perfect tenses",available:!0},{number:2,title:"Conditionals",subtitle:"Zero to third, mixed conditionals and wish",available:!0},{number:3,title:"Verb patterns",subtitle:"Gerund or infinitive, stop/remember/try, look forward to + -ing",available:!0},{number:4,title:"Passive, reported speech, deduction",subtitle:"The passive, reporting what people said, must/might/can't have",available:!0},{number:5,title:"Word partners",subtitle:"Collocations and phrasal verbs",available:!0},{number:6,title:"Linking, articles, countables",subtitle:"Linking words, a/the/no article, countable and uncountable nouns",available:!0},{number:7,title:"Review and test",subtitle:"Your error log, a full review and a B2-style test",available:!0}].map(e=>n(o.a,e,`day meta ${e.number}`)).sort((e,t)=>e.number-t.number),r=n(o.P,a,"day 7"),d=n(o.K,[{id:"diag-be-film-starts",prompt:"Hurry up! The film ___ in ten minutes.",options:["is start","starts","is started","starting"],answer:1,category:"be-verb"},{id:"diag-vp-enjoy-trying",prompt:"I really enjoy ___ new recipes at the weekend.",options:["to try","try","trying"],answer:2,category:"verb-patterns"},{id:"diag-perf-since-2020",prompt:"I ___ for this company since 2020.",options:["work","have worked","am working","worked"],answer:1,category:"perfect"},{id:"diag-coll-waste-of-money",prompt:"Buying a new phone every year is a ___ of money.",options:["trash","spending","waste"],answer:2,category:"collocations"},{id:"diag-count-advice",prompt:"My friend gave me ___ before the interview.",options:["a useful advice","some useful advice","some useful advices","useful advices"],answer:1,category:"countable"},{id:"diag-be-prices-risen",prompt:"Food prices ___ a lot since last year.",options:["have risen","are risen","have been risen","were risen"],answer:0,category:"be-verb"},{id:"diag-vp-suggested-drinking",prompt:"My doctor suggested ___ less coffee.",options:["to drink","me to drink","drinking","drink"],answer:2,category:"verb-patterns"},{id:"diag-perf-third-conditional",prompt:"If we ___ earlier, we wouldn't have missed the train.",options:["left","would leave","have left","had left"],answer:3,category:"perfect"},{id:"diag-coll-carry-out-survey",prompt:"Last month our team ___ a survey of 500 customers.",options:["carried on","spent","carried out"],answer:2,category:"collocations"},{id:"diag-count-assistance",prompt:"If you need any ___ with your luggage, please call reception.",options:["assistance","assistant","assistances"],answer:0,category:"countable"}],"diagnostic");e.s(["J",0,i,"h",0,function(e,t){return e.topics.find(e=>e.id===t)},"T",0,function(e){return i.find(t=>t.number===e)??null},"j",0,function(){return d},"R",0,function(){return r},"v",0,function(){return s}],46005)}]);